CREATE OR REPLACE FUNCTION public.apply_management_alert_preference()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE topic text; member text; member_kind text; retained text[] := ARRAY[]::text[];
BEGIN
  topic := management_alert_topic(NEW.source_kind,NEW.type);
  IF NEW.source_kind='MANAGER_SUMMARY' AND cardinality(NEW.item_keys)>0 THEN
    FOREACH member IN ARRAY NEW.item_keys LOOP
      BEGIN
        BEGIN member_kind := (member::jsonb)->>0;
        EXCEPTION WHEN invalid_text_representation THEN member_kind := substring(member from '^(?:test|production):[0-9-]+:(TIME_OFF|EXCHANGE|CALLOUT):');
        END;
        IF management_alert_on(NEW.employee_id,management_alert_topic(member_kind,NULL)) THEN
          retained := array_append(retained,member);
        END IF;
      EXCEPTION WHEN invalid_text_representation THEN
        -- Retain legacy/non-JSON keys; never guess their topic.
        retained := array_append(retained,member);
      END;
    END LOOP;
    NEW.item_keys := retained;
    IF cardinality(retained)=0 THEN
      NEW.cancelled_at := COALESCE(NEW.cancelled_at,clock_timestamp());
      NEW.push_state := 'cancelled';
      NEW.management_alert_suppressed := true;
    END IF;
  ELSIF NOT management_alert_on(NEW.employee_id,topic) THEN
    NEW.cancelled_at := COALESCE(NEW.cancelled_at,clock_timestamp());
    NEW.push_state := 'cancelled';
    NEW.management_alert_suppressed := true;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.auth_passkey_authority_loss()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target text; why text;
BEGIN
  IF TG_TABLE_NAME='employees' THEN
    IF OLD.active AND NOT NEW.active THEN target:=NEW.id;why:='account_disabled'; END IF;
  ELSIF TG_TABLE_NAME='account_deletion_requests' THEN
    IF NEW.employee_id IS NOT NULL AND NEW.status IN ('received','processing') THEN
      target:=NEW.employee_id;why:='account_deletion';
      UPDATE employees SET updated_at=clock_timestamp() WHERE id=target;
    END IF;
  ELSIF TG_OP='DELETE' THEN
    target:=OLD.employee_id;why:='credential_reset';
  ELSE
    IF NEW.password_hash IS DISTINCT FROM OLD.password_hash OR NEW.password_updated_at IS DISTINCT FROM OLD.password_updated_at
      THEN target:=NEW.employee_id;why:='credential_reset'; END IF;
  END IF;
  IF target IS NOT NULL THEN
    WITH revoked AS (
      UPDATE employee_passkeys SET revoked_at=clock_timestamp(),revocation_reason=why
      WHERE employee_id=target AND revoked_at IS NULL RETURNING id
    )
    INSERT INTO auth_passkey_audit(employee_id,passkey_id,event,reason)
      SELECT target,id,'revoke',why FROM revoked;
    DELETE FROM auth_passkey_challenges WHERE employee_id=target;
    IF why='account_deletion' THEN
      DELETE FROM employee_sessions WHERE employee_id=target;
      UPDATE calendar_subscriptions SET revoked_at=clock_timestamp(),revocation_reason='account_loss'
        WHERE employee_id=target AND revoked_at IS NULL;
    END IF;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.clocker_apply_punch(p_employee text, p_device text, p_location text, p_credential_version integer, p_command uuid, p_action text, p_expected jsonb, p_request_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
 e time_entries%ROWTYPE; b break_entries%ROWTYPE; saved clocker_command_ledger%ROWTYPE;
 before_state jsonb; expected_state jsonb; result_state jsonb; receipt jsonb;
 performed timestamptz; last_boundary timestamptz; entry_id text; break_id text;
 selected_type clocker_break_types%ROWTYPE; break_settings jsonb;
BEGIN
 -- Lock order: workspace -> employee -> identity/device -> time/break state.
 -- The employee lock is also acquired by the caller before device locks.
 PERFORM id FROM employees WHERE id=p_employee FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_AUTH_REQUIRED'; END IF;
 SELECT * INTO saved FROM clocker_command_ledger WHERE device_id=p_device AND command_id=p_command;
 IF FOUND THEN
  IF saved.employee_id<>p_employee OR saved.credential_version<>p_credential_version
    OR saved.request_hash<>p_request_hash OR saved.action<>p_action THEN
   RAISE EXCEPTION 'clocker_punch_COMMAND_REUSED';
  END IF;
  RETURN saved.result;
 END IF;
 INSERT INTO clocker_employee_clock_state(employee_id) VALUES(p_employee) ON CONFLICT DO NOTHING;
 PERFORM employee_id FROM clocker_employee_clock_state WHERE employee_id=p_employee FOR UPDATE;
 SELECT * INTO e FROM time_entries WHERE employee_id=p_employee AND clock_out_at IS NULL FOR UPDATE;
 IF e.id IS NOT NULL THEN
  PERFORM id FROM break_entries WHERE time_entry_id=e.id ORDER BY id FOR UPDATE;
  SELECT * INTO b FROM break_entries WHERE time_entry_id=e.id AND break_end_at IS NULL;
 END IF;
 before_state=clocker_punch_snapshot(p_employee);
 expected_state=jsonb_build_object('revision',before_state->'revision',
  'timeEntryId',before_state->'entry'->'id','timeEntryVersion',before_state->'entry'->'version',
  'breakEntryId',before_state->'break'->'id','breakEntryVersion',before_state->'break'->'version');
 IF expected_state IS DISTINCT FROM (p_expected - 'breakType') THEN RAISE EXCEPTION 'clocker_punch_STALE_STATE'; END IF;
 IF e.id IS NOT NULL AND e.location_id<>p_location THEN RAISE EXCEPTION 'clocker_punch_OTHER_LOCATION'; END IF;
 IF p_action NOT IN ('CLOCK_IN','START_BREAK','END_BREAK','CLOCK_OUT')
   OR (p_action='CLOCK_IN' AND e.id IS NOT NULL)
   OR (p_action<>'CLOCK_IN' AND e.id IS NULL)
   OR (p_action='START_BREAK' AND e.status<>'CLOCKED_IN')
   OR (p_action='END_BREAK' AND e.status<>'ON_BREAK') THEN
  RAISE EXCEPTION 'clocker_punch_INVALID_TRANSITION';
 END IF;
 -- Validate the observed type under a lock. Catalog changes affect future starts only.
 -- Duplicate commands returned their original immutable receipt above.
 break_settings=b.break_type_snapshot;
 IF p_action='START_BREAK' THEN
  SELECT bt.* INTO selected_type FROM clocker_break_types bt JOIN locations l ON l.workspace_id=bt.workspace_id
   WHERE l.id=p_location AND bt.id=p_expected->'breakType'->>'id' FOR SHARE OF bt;
  IF selected_type.id IS NULL OR NOT selected_type.active
    OR selected_type.version::text IS DISTINCT FROM (p_expected->'breakType'->>'version') THEN
   RAISE EXCEPTION 'clocker_punch_BREAK_TYPE_CHANGED';
  END IF;
  break_settings=jsonb_build_object('id',selected_type.id,'version',selected_type.version,'name',selected_type.name,
   'category',selected_type.category,'targetMinutes',selected_type.target_minutes);
 END IF;
 -- Database wall time is sampled after all business locks, never from the client
 -- and never transaction-start now(). Clock regressions fail instead of altering history.
 performed=clock_timestamp();
 IF e.id IS NULL THEN
  SELECT max(clock_out_at) INTO last_boundary FROM time_entries WHERE employee_id=p_employee;
 ELSE
  SELECT GREATEST(e.clock_in_at,max(COALESCE(break_end_at,break_start_at))) INTO last_boundary
   FROM break_entries WHERE time_entry_id=e.id;
 END IF;
 IF performed<last_boundary THEN RAISE EXCEPTION 'clocker_punch_CLOCK_INVALID'; END IF;
 entry_id=e.id; break_id=b.id;
 IF p_action='CLOCK_IN' THEN
  entry_id=gen_random_uuid()::text;
  INSERT INTO time_entries(id,employee_id,location_id,device_id,clock_in_at,status,created_at,updated_at)
   VALUES(entry_id,p_employee,p_location,p_device,performed,'CLOCKED_IN',performed,performed);
  IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF;
 ELSIF p_action='START_BREAK' THEN
  break_id=gen_random_uuid()::text;
  INSERT INTO break_entries(id,time_entry_id,break_start_at,break_type_id,break_type_snapshot) VALUES(break_id,entry_id,performed,selected_type.id,break_settings);
  IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF;
  UPDATE time_entries SET status='ON_BREAK',version=version+1,updated_at=performed WHERE id=entry_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF;
 ELSIF p_action='END_BREAK' THEN
  UPDATE break_entries SET break_end_at=performed,version=version+1 WHERE id=break_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF;
  UPDATE time_entries SET status='CLOCKED_IN',version=version+1,updated_at=performed WHERE id=entry_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF;
 ELSE
  IF break_id IS NOT NULL THEN UPDATE break_entries SET break_end_at=performed,version=version+1 WHERE id=break_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF; END IF;
  UPDATE time_entries SET status='CLOCKED_OUT',clock_out_at=performed,version=version+1,updated_at=performed WHERE id=entry_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF;
 END IF;
 UPDATE clocker_employee_clock_state SET revision=revision+1 WHERE employee_id=p_employee;
  IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF;
 result_state=clocker_punch_snapshot(p_employee);
 receipt=jsonb_build_object('commandId',p_command,'action',p_action,'timeEntryId',entry_id,
  'breakEntryId',break_id,'performedAt',performed,'snapshot',result_state,'breakType',break_settings);
 INSERT INTO clocker_command_ledger(device_id,command_id,employee_id,credential_version,request_hash,action,time_entry_id,performed_at,result)
  VALUES(p_device,p_command,p_employee,p_credential_version,p_request_hash,p_action,entry_id,performed,receipt);
 IF NOT FOUND THEN RAISE EXCEPTION 'clocker_punch_INTEGRITY'; END IF;
 RETURN receipt;
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_capture_schedule_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE raw text;
BEGIN
 raw=NULLIF(current_setting('nevora.clocker_schedule_capture',true),'');
 IF raw IS NULL THEN NEW.schedule_context=NULL;
 ELSE NEW.schedule_context=clocker_resolve_schedule_context(raw::jsonb,NEW.employee_id,NEW.location_id,NEW.clock_in_at);
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_device_location_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.location_id IS DISTINCT FROM OLD.location_id THEN
    RAISE EXCEPTION 'clocker_device_location_immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_photo_binding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.workspace_id,NEW.device_id,NEW.command_id,NEW.employee_id,NEW.location_id,
   NEW.credential_version,NEW.action,NEW.performed_at,NEW.policy_version,NEW.notice_profile_version,NEW.upload_deadline)
   IS DISTINCT FROM ROW(OLD.workspace_id,OLD.device_id,OLD.command_id,OLD.employee_id,OLD.location_id,
   OLD.credential_version,OLD.action,OLD.performed_at,OLD.policy_version,OLD.notice_profile_version,OLD.upload_deadline) THEN
   RAISE EXCEPTION 'clocker_photo_COMMAND_REUSED';
 END IF;
 IF TG_OP='UPDATE' AND OLD.expires_at IS NOT NULL AND (NEW.expires_at IS NULL OR NEW.expires_at>OLD.expires_at) THEN
   RAISE EXCEPTION 'clocker_photo_INVALID_INPUT';
 END IF;
 IF TG_OP='UPDATE' AND ((OLD.state='expired' AND NEW.state<>'expired') OR
   (OLD.state='removed' AND NEW.state<>'removed') OR
   (OLD.removed_at IS NOT NULL AND ROW(NEW.removed_at,NEW.removed_by) IS DISTINCT FROM ROW(OLD.removed_at,OLD.removed_by)) OR
   (OLD.state='not_required' AND NEW.state<>'not_required') OR
   (OLD.uploaded_at IS NOT NULL AND OLD.jpeg IS NULL AND NEW.jpeg IS NOT NULL)) THEN
   RAISE EXCEPTION 'clocker_photo_COMMAND_REUSED';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM clocker_command_ledger ledger JOIN clocker_devices d ON d.id=ledger.device_id
   JOIN locations l ON l.id=d.location_id JOIN employees e ON e.id=ledger.employee_id JOIN locations employee_home ON employee_home.id=e.primary_location_id
   WHERE ledger.device_id=NEW.device_id AND ledger.command_id=NEW.command_id AND ledger.employee_id=NEW.employee_id
   AND l.workspace_id=NEW.workspace_id AND employee_home.workspace_id=NEW.workspace_id AND d.location_id=NEW.location_id
   AND ledger.credential_version=NEW.credential_version AND ledger.action=NEW.action AND ledger.performed_at=NEW.performed_at) THEN
   RAISE EXCEPTION 'clocker_photo_AUTH_REQUIRED';
 END IF;
 IF NEW.jpeg IS NOT NULL AND (NEW.sha256 IS DISTINCT FROM encode(sha256(NEW.jpeg),'hex') OR NEW.uploaded_at IS NULL) THEN
   RAISE EXCEPTION 'clocker_photo_INVALID_INPUT';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_photo_capture_expectation(p_workspace text, p_device text, p_command uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE saved clocker_command_ledger%ROWTYPE; policy clocker_photo_policy%ROWTYPE; profile clocker_photo_notice_profiles%ROWTYPE; photo clocker_punch_photos%ROWTYPE; needed boolean;
BEGIN
 SELECT ledger.* INTO saved FROM clocker_command_ledger ledger
 JOIN clocker_devices d ON d.id=ledger.device_id JOIN locations l ON l.id=d.location_id
 JOIN employees e ON e.id=ledger.employee_id JOIN locations employee_home ON employee_home.id=e.primary_location_id AND employee_home.workspace_id=l.workspace_id
 WHERE l.workspace_id=p_workspace AND ledger.device_id=p_device AND ledger.command_id=p_command;
 IF NOT FOUND THEN RETURN jsonb_build_object('commandId',p_command,'state','unknown'); END IF;
 SELECT * INTO policy FROM clocker_photo_policy WHERE workspace_id=p_workspace FOR SHARE;
 SELECT * INTO profile FROM clocker_photo_notice_profiles WHERE workspace_id=p_workspace FOR SHARE;
 needed=COALESCE(policy.enabled AND saved.action=ANY(policy.events),false);
 INSERT INTO clocker_punch_photos(workspace_id,device_id,command_id,employee_id,location_id,credential_version,action,performed_at,
   policy_version,notice_profile_version,state,upload_deadline,expires_at)
 SELECT p_workspace,saved.device_id,saved.command_id,saved.employee_id,d.location_id,saved.credential_version,saved.action,saved.performed_at,
   COALESCE(policy.version,0),COALESCE(profile.version,0),CASE WHEN needed THEN 'pending' ELSE 'not_required' END,
   CASE WHEN needed THEN saved.performed_at+interval '300 seconds' END,
   CASE WHEN needed THEN saved.performed_at+make_interval(days=>policy.retention_days) END
 FROM clocker_devices d JOIN locations l ON l.id=d.location_id WHERE l.workspace_id=p_workspace AND d.id=saved.device_id
 ON CONFLICT(workspace_id,device_id,command_id) DO NOTHING;
 SELECT * INTO photo FROM clocker_punch_photos WHERE workspace_id=p_workspace AND device_id=p_device AND command_id=p_command;
 IF NOT FOUND THEN RAISE EXCEPTION 'clocker_photo_UNAVAILABLE'; END IF;
 RETURN clocker_photo_status_value(photo);
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_photo_missing(p_workspace text, p_device text, p_employee text, p_generation integer, p_command uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE photo clocker_punch_photos%ROWTYPE;
BEGIN
 IF p_code IS NULL OR p_code NOT IN ('CAMERA_DENIED','CAMERA_UNAVAILABLE','CAPTURE_FAILED','UPLOAD_FAILED','EMPLOYEE_CHANGED','PHOTO_ALTERNATIVE') THEN RAISE EXCEPTION 'clocker_photo_INVALID_INPUT'; END IF;
 SELECT * INTO photo FROM clocker_punch_photos WHERE workspace_id=p_workspace AND device_id=p_device AND command_id=p_command
   AND employee_id=p_employee AND credential_version=p_generation FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('commandId',p_command,'state','unknown'); END IF;
 IF photo.state IN ('stored','not_required','expired','removed') OR photo.expires_at<=clock_timestamp() THEN RETURN clocker_photo_status_value(photo); END IF;
 IF photo.failure_code IS NOT NULL AND photo.failure_code<>p_code THEN RAISE EXCEPTION 'clocker_photo_COMMAND_REUSED'; END IF;
 UPDATE clocker_punch_photos SET state='missing',failure_code=p_code WHERE workspace_id=p_workspace AND device_id=p_device AND command_id=p_command RETURNING * INTO photo;
 RETURN clocker_photo_status_value(photo);
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_photo_platform_cleanup(p_workspace text, p_invocation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE config public.clocker_photo_platform_lifecycle; prior public.clocker_photo_cleanup_runs;
 expired integer; orphaned integer; pending boolean;
BEGIN
 IF p_invocation IS NULL OR length(p_invocation) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'clocker_cleanup_invalid'; END IF;
 SELECT * INTO config FROM public.clocker_photo_platform_lifecycle WHERE workspace_id=p_workspace FOR UPDATE;
 IF NOT FOUND OR session_user<>config.worker_role_name OR NOT EXISTS(
  SELECT 1 FROM public.workspaces WHERE id=p_workspace AND singleton=true AND active=true
 ) THEN RAISE EXCEPTION 'clocker_cleanup_denied'; END IF;
 SELECT * INTO prior FROM public.clocker_photo_cleanup_runs WHERE workspace_id=p_workspace AND invocation_id=p_invocation;
 IF FOUND THEN RETURN jsonb_build_object('expired',prior.expired_count,'orphanFinalized',prior.orphan_count,'backlog',prior.backlog); END IF;
 PERFORM set_config('nevora.clocker.photo_workspace',p_workspace,true);
 WITH selected AS (
  SELECT device_id,command_id FROM public.clocker_punch_photos WHERE workspace_id=p_workspace AND expires_at<=clock_timestamp()
  AND state NOT IN ('expired','not_required','removed') ORDER BY expires_at,device_id,command_id LIMIT 500 FOR UPDATE SKIP LOCKED
 ), changed AS (
  UPDATE public.clocker_punch_photos p SET state='expired',jpeg=NULL,sha256=NULL,width=NULL,height=NULL FROM selected s
  WHERE p.workspace_id=p_workspace AND p.device_id=s.device_id AND p.command_id=s.command_id RETURNING 1
 ) SELECT count(*)::integer INTO expired FROM changed;
 WITH selected AS (
  SELECT device_id,command_id FROM public.clocker_punch_photos WHERE workspace_id=p_workspace AND state='pending'
  AND upload_deadline<=clock_timestamp() AND expires_at>clock_timestamp() ORDER BY upload_deadline,device_id,command_id LIMIT 500 FOR UPDATE SKIP LOCKED
 ), changed AS (
  UPDATE public.clocker_punch_photos p SET state='missing',failure_code='UPLOAD_FAILED' FROM selected s
  WHERE p.workspace_id=p_workspace AND p.device_id=s.device_id AND p.command_id=s.command_id RETURNING 1
 ) SELECT count(*)::integer INTO orphaned FROM changed;
 SELECT EXISTS(SELECT 1 FROM public.clocker_punch_photos WHERE workspace_id=p_workspace
  AND ((expires_at<=clock_timestamp() AND state NOT IN ('expired','not_required','removed'))
   OR (state='pending' AND upload_deadline<=clock_timestamp()))) INTO pending;
 INSERT INTO public.clocker_photo_cleanup_runs(workspace_id,invocation_id,expired_count,orphan_count,backlog)
 VALUES(p_workspace,p_invocation,expired,orphaned,pending);
 IF NOT pending THEN UPDATE public.clocker_photo_platform_lifecycle SET last_success_at=clock_timestamp() WHERE workspace_id=p_workspace; END IF;
 RETURN jsonb_build_object('expired',expired,'orphanFinalized',orphaned,'backlog',pending);
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_photo_remove(p_workspace text, p_actor text, p_device text, p_command uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE photo clocker_punch_photos%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM employees e JOIN locations employee_home ON employee_home.id=e.primary_location_id WHERE employee_home.workspace_id=p_workspace AND e.id=p_actor AND e.active AND e.role='OWNER') THEN
  RAISE EXCEPTION 'clocker_photo_AUTH_REQUIRED'; END IF;
 SELECT * INTO photo FROM clocker_punch_photos WHERE workspace_id=p_workspace AND device_id=p_device AND command_id=p_command FOR UPDATE;
 IF NOT FOUND OR photo.state IN ('not_required','expired') OR photo.expires_at<=clock_timestamp() THEN
  RETURN jsonb_build_object('reference',jsonb_build_object('deviceId',p_device,'commandId',p_command),'state','unavailable','removedAt',NULL); END IF;
 IF photo.state='removed' THEN
  RETURN jsonb_build_object('reference',jsonb_build_object('deviceId',p_device,'commandId',p_command),'state','already_removed','removedAt',photo.removed_at); END IF;
 UPDATE clocker_punch_photos SET state='removed',jpeg=NULL,sha256=NULL,width=NULL,height=NULL,removed_at=clock_timestamp(),removed_by=p_actor
  WHERE workspace_id=p_workspace AND device_id=p_device AND command_id=p_command RETURNING * INTO photo;
 INSERT INTO clocker_photo_access_events(workspace_id,actor_employee_id,device_id,command_id,kind)
  VALUES(p_workspace,p_actor,p_device,p_command,'OWNER_REMOVED');
 RETURN jsonb_build_object('reference',jsonb_build_object('deviceId',p_device,'commandId',p_command),'state','removed','removedAt',photo.removed_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_photo_save_notice(p_workspace text, p_actor text, p_expected integer, p_contact text, p_instructions text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE profile clocker_photo_notice_profiles%ROWTYPE; revision integer;
BEGIN
 PERFORM id FROM workspaces WHERE id=p_workspace FOR UPDATE;
 SELECT * INTO profile FROM clocker_photo_notice_profiles WHERE workspace_id=p_workspace FOR UPDATE;
 IF COALESCE(profile.version,0) IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'clocker_photo_POLICY_CHANGED'; END IF;
 revision=p_expected+1;
 INSERT INTO clocker_photo_notice_profiles(workspace_id,version,assistance_contact,assistance_instructions,updated_by)
 VALUES(p_workspace,revision,p_contact,p_instructions,p_actor)
 ON CONFLICT(workspace_id) DO UPDATE SET version=EXCLUDED.version,assistance_contact=EXCLUDED.assistance_contact,
  assistance_instructions=EXCLUDED.assistance_instructions,updated_by=EXCLUDED.updated_by,updated_at=clock_timestamp();
 SELECT * INTO profile FROM clocker_photo_notice_profiles WHERE workspace_id=p_workspace;
 INSERT INTO clocker_photo_notice_revisions(workspace_id,version,actor_employee_id,profile)
 VALUES(p_workspace,revision,p_actor,jsonb_build_object('version',revision,'assistanceContact',profile.assistance_contact,
  'assistanceInstructions',profile.assistance_instructions));
 RETURN jsonb_build_object('version',revision,'assistanceContact',profile.assistance_contact,'assistanceInstructions',profile.assistance_instructions);
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_photo_save_policy(p_workspace text, p_actor text, p_expected integer, p_enabled boolean, p_events text[], p_retention integer, p_behavior text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE policy clocker_photo_policy%ROWTYPE; revision integer; effective_retention integer; effective_behavior text;
BEGIN
 -- Workspace lock serializes initial insert and later CAS saves. Authority is
 -- checked before/after by the current server proof adapter, never by actor IDs alone.
 PERFORM id FROM workspaces WHERE id=p_workspace FOR UPDATE;
 SELECT * INTO policy FROM clocker_photo_policy WHERE workspace_id=p_workspace FOR UPDATE;
 IF COALESCE(policy.version,0) IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'clocker_photo_POLICY_CHANGED'; END IF;
 -- First-save NULL values receive the approved new-company defaults only.
 -- Existing disabled NULL policies retain their explicit stored preferences.
 effective_retention=CASE WHEN p_expected=0 THEN COALESCE(p_retention,30) ELSE p_retention END;
 effective_behavior=CASE WHEN p_expected=0 THEN COALESCE(p_behavior,'ALLOW_WITH_EXCEPTION') ELSE p_behavior END;
 revision=p_expected+1;
 INSERT INTO clocker_photo_policy(workspace_id,version,enabled,events,retention_days,failure_behavior,updated_by)
 VALUES(p_workspace,revision,p_enabled,p_events,effective_retention,effective_behavior,p_actor)
 ON CONFLICT(workspace_id) DO UPDATE SET version=EXCLUDED.version,enabled=EXCLUDED.enabled,events=EXCLUDED.events,
   retention_days=EXCLUDED.retention_days,failure_behavior=EXCLUDED.failure_behavior,updated_by=EXCLUDED.updated_by,updated_at=clock_timestamp();
 SELECT * INTO policy FROM clocker_photo_policy WHERE workspace_id=p_workspace;
 INSERT INTO clocker_photo_policy_revisions(workspace_id,version,actor_employee_id,policy)
 VALUES(p_workspace,revision,p_actor,jsonb_build_object('version',revision,'enabled',policy.enabled,'events',policy.events,
   'retentionDays',policy.retention_days,'failureBehavior',policy.failure_behavior));
 -- A shorter selected retention applies to existing photos; longer settings
 -- never extend a previously promised image lifetime.
 IF effective_retention IS NOT NULL THEN UPDATE clocker_punch_photos SET expires_at=LEAST(expires_at,performed_at+make_interval(days=>effective_retention))
   WHERE workspace_id=p_workspace AND expires_at IS NOT NULL; END IF;
 RETURN jsonb_build_object('version',revision,'enabled',policy.enabled,'events',policy.events,
   'retentionDays',policy.retention_days,'failureBehavior',policy.failure_behavior);
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_photo_upload(p_workspace text, p_device text, p_employee text, p_generation integer, p_command uuid, p_jpeg bytea, p_sha256 text, p_width integer, p_height integer, p_policy_version integer, p_profile_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE photo clocker_punch_photos%ROWTYPE;
BEGIN
 -- Match policy-save lock order; prevent policy/profile changes between the
 -- version assertion and image finalization without a photo/policy deadlock.
 PERFORM id FROM workspaces WHERE id=p_workspace FOR SHARE;
 SELECT * INTO photo FROM clocker_punch_photos WHERE workspace_id=p_workspace AND device_id=p_device AND command_id=p_command
   AND employee_id=p_employee AND credential_version=p_generation FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('commandId',p_command,'state','unknown'); END IF;
 IF photo.state IN ('not_required','expired','removed') OR photo.expires_at<=clock_timestamp() THEN RETURN clocker_photo_status_value(photo); END IF;
 IF photo.policy_version IS DISTINCT FROM p_policy_version OR photo.notice_profile_version IS DISTINCT FROM p_profile_version OR
   NOT EXISTS(SELECT 1 FROM clocker_photo_policy WHERE workspace_id=p_workspace AND version=p_policy_version) OR
   NOT EXISTS(SELECT 1 FROM clocker_photo_notice_profiles WHERE workspace_id=p_workspace AND version=p_profile_version) THEN
  RAISE EXCEPTION 'clocker_photo_POLICY_CHANGED'; END IF;
 IF photo.state='stored' THEN
   IF photo.sha256 IS DISTINCT FROM p_sha256 THEN RAISE EXCEPTION 'clocker_photo_COMMAND_REUSED'; END IF;
   RETURN clocker_photo_status_value(photo);
 END IF;
 IF photo.upload_deadline<=clock_timestamp() THEN RETURN clocker_photo_status_value(photo); END IF;
 IF p_jpeg IS NULL OR p_width IS NULL OR p_height IS NULL OR p_sha256 IS NULL
   OR octet_length(p_jpeg) NOT BETWEEN 20 AND 524288 OR p_width NOT BETWEEN 1 AND 640 OR p_height NOT BETWEEN 1 AND 640
   OR p_sha256 IS DISTINCT FROM encode(sha256(p_jpeg),'hex') THEN RAISE EXCEPTION 'clocker_photo_INVALID_INPUT'; END IF;
 UPDATE clocker_punch_photos SET state='stored',jpeg=p_jpeg,sha256=p_sha256,width=p_width,height=p_height,
   uploaded_at=clock_timestamp(),failure_code=NULL WHERE workspace_id=p_workspace AND device_id=p_device AND command_id=p_command RETURNING * INTO photo;
 RETURN clocker_photo_status_value(photo);
END;
$function$

