CREATE OR REPLACE FUNCTION public.clocker_punch_snapshot(p_employee text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE e time_entries%ROWTYPE; b break_entries%ROWTYPE; r integer;
BEGIN
 SELECT revision INTO r FROM clocker_employee_clock_state WHERE employee_id=p_employee;
 IF EXISTS(SELECT 1 FROM break_entries x JOIN time_entries t ON t.id=x.time_entry_id
   WHERE t.employee_id=p_employee AND (x.break_start_at<t.clock_in_at OR
    (t.clock_out_at IS NOT NULL AND (x.break_end_at IS NULL OR x.break_end_at>t.clock_out_at)))) THEN
  RAISE EXCEPTION 'clocker_punch_INTEGRITY';
 END IF;
 SELECT * INTO e FROM time_entries WHERE employee_id=p_employee AND clock_out_at IS NULL;
 IF e.id IS NULL THEN RETURN jsonb_build_object('revision',COALESCE(r,0),'entry',NULL,'break',NULL); END IF;
 SELECT * INTO b FROM break_entries WHERE time_entry_id=e.id AND break_end_at IS NULL;
 IF (e.status='ON_BREAK') IS DISTINCT FROM (b.id IS NOT NULL)
  OR EXISTS(SELECT 1 FROM break_entries x WHERE x.time_entry_id=e.id AND x.break_start_at<e.clock_in_at)
  OR EXISTS(SELECT 1 FROM break_entries x JOIN break_entries y ON x.time_entry_id=y.time_entry_id AND x.id<y.id
    WHERE x.time_entry_id=e.id AND x.break_start_at<COALESCE(y.break_end_at,'infinity'::timestamptz)
      AND y.break_start_at<COALESCE(x.break_end_at,'infinity'::timestamptz)) THEN
  RAISE EXCEPTION 'clocker_punch_INTEGRITY';
 END IF;
 RETURN jsonb_build_object('revision',COALESCE(r,0),
  'entry',jsonb_build_object('id',e.id,'locationId',e.location_id,'clockInAt',e.clock_in_at,'version',e.version,'status',e.status),
  'break',CASE WHEN b.id IS NULL THEN NULL ELSE jsonb_build_object('id',b.id,'breakStartAt',b.break_start_at,'version',b.version,'type',b.break_type_snapshot) END);
END;
$function$

CREATE OR REPLACE FUNCTION public.clocker_resolve_schedule_context(prepared jsonb, p_employee text, p_location text, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
 candidate jsonb; selected jsonb; candidate_count integer:=0; uncertain_count integer:=0;
 status text; reason text; location_workspace text; configured_zone text;
BEGIN
 SELECT w.id,w.time_zone INTO location_workspace,configured_zone
 FROM locations l JOIN workspaces w ON w.id=l.workspace_id WHERE l.id=p_location;
 IF prepared->'version' IS DISTINCT FROM '1'::jsonb
   OR prepared->>'employeeId' IS DISTINCT FROM p_employee
   OR prepared->>'locationId' IS DISTINCT FROM p_location
   OR prepared->>'workspaceId' IS DISTINCT FROM location_workspace
   OR prepared->>'timeZone' IS DISTINCT FROM configured_zone
   OR jsonb_typeof(prepared->'candidates') IS DISTINCT FROM 'array'
   OR jsonb_typeof(prepared->'reviewedRevisionIds') IS DISTINCT FROM 'array'
   OR NULLIF(prepared->>'windowStartAt','') IS NULL
   OR NULLIF(prepared->>'windowEndAt','') IS NULL THEN
  RAISE EXCEPTION 'clocker_punch_SCHEDULE_CHANGED';
 END IF;
 IF p_at IS NULL OR p_at < (prepared->>'windowStartAt')::timestamptz
    OR p_at >= (prepared->>'windowEndAt')::timestamptz THEN
  RAISE EXCEPTION 'clocker_punch_SCHEDULE_CHANGED';
 END IF;
 FOR candidate IN SELECT value FROM jsonb_array_elements(prepared->'candidates') LOOP
  IF p_at >= (candidate->>'startAt')::timestamptz AND p_at < (candidate->>'endAt')::timestamptz THEN
   candidate_count=candidate_count+1;
   IF (candidate->>'uncertain')::boolean THEN uncertain_count=uncertain_count+1;
   ELSIF selected IS NULL THEN selected=candidate; END IF;
  END IF;
 END LOOP;
 IF candidate_count=0 THEN status='UNMATCHED';reason='NO_MATCH';selected=NULL;
 ELSIF uncertain_count>0 THEN status='AMBIGUOUS';reason='UNRESOLVED_LOCAL_TIME';selected=NULL;
 ELSIF candidate_count>1 THEN status='AMBIGUOUS';reason='OVERLAPPING_SHIFTS';selected=NULL;
 ELSE status='MATCHED';reason=NULL; END IF;
 RETURN jsonb_build_object('version',1,'status',status,'timeZone',prepared->>'timeZone',
  'capturedAt',p_at,'candidateCount',candidate_count,'reviewedRevisionIds',prepared->'reviewedRevisionIds',
  'reason',reason,'match',CASE WHEN selected IS NULL THEN 'null'::jsonb ELSE jsonb_build_object(
   'revisionId',selected->>'revisionId','revisionNumber',(selected->>'revisionNumber')::integer,
   'publishedShiftId',selected->>'publishedShiftId','sourceShiftId',selected->'sourceShiftId',
   'scheduleId',selected->>'scheduleId','positionId',selected->'positionId','positionName',selected->'positionName'
  ) END);
END;
$function$

CREATE OR REPLACE FUNCTION public.communication_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r communication_revisions%ROWTYPE; c communications%ROWTYPE; h integer; actor text;
BEGIN
 IF TG_TABLE_NAME='communications' THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'communication_history_immutable'; END IF;
  -- Author eligibility is a creation-time fact; later deactivation or relocation
  -- must not invalidate immutable history. New revision/lifecycle actors retain
  -- their current eligibility guards; protected commands own session authority.
  IF TG_OP='INSERT' AND NOT communication_same_workspace(NEW.author_employee_id,NEW.workspace_id) THEN RAISE EXCEPTION 'communication_actor_workspace'; END IF;
  IF TG_OP='INSERT' AND NEW.state<>'DRAFT' THEN RAISE EXCEPTION 'communication_stage_required'; END IF;
  IF TG_OP='UPDATE' THEN
   IF (NEW.id,NEW.workspace_id,NEW.author_employee_id,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.workspace_id,OLD.author_employee_id,OLD.created_at) OR OLD.state='WITHDRAWN' OR NEW.state='DRAFT' THEN RAISE EXCEPTION 'communication_identity_immutable'; END IF;
   SELECT * INTO r FROM communication_revisions WHERE workspace_id=NEW.workspace_id AND communication_id=NEW.id AND id=NEW.head_revision_id;
   IF r.id IS NULL OR r.published_at IS NULL THEN RAISE EXCEPTION 'communication_published_head_required'; END IF;
   IF NEW.state='WITHDRAWN' AND (OLD.state<>'PUBLISHED' OR NEW.head_revision_id<>OLD.head_revision_id) THEN RAISE EXCEPTION 'communication_withdraw_identity'; END IF;
   IF OLD.head_revision_id IS NOT NULL AND NEW.state='PUBLISHED' THEN
    SELECT version INTO h FROM communication_revisions WHERE id=OLD.head_revision_id;
    IF r.version<=h THEN RAISE EXCEPTION 'communication_head_must_advance'; END IF;
   END IF;
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO c FROM communications WHERE workspace_id=NEW.workspace_id AND id=NEW.communication_id FOR UPDATE;
 IF c.id IS NULL THEN RAISE EXCEPTION 'communication_parent_identity'; END IF;
 IF TG_TABLE_NAME='communication_revisions' THEN
  actor=NEW.created_by;
  IF c.state='WITHDRAWN' THEN RAISE EXCEPTION 'communication_withdrawn'; END IF;
  IF NOT EXISTS(SELECT 1 FROM employees WHERE id=actor AND active AND (role IN('OWNER','MANAGER') OR (role IN('EMPLOYEE','LEAD') AND NEW.type='TODAYS_TEAM' AND NEW.acknowledgement<>'REQUIRED'))) THEN RAISE EXCEPTION 'communication_author_role'; END IF;
  IF NEW.content_hash<>communication_content_hash(ARRAY[NEW.type,NEW.scope_kind,NEW.location_id,NEW.business_date::text,NEW.source_shift_id,NEW.assignment_episode_id,NEW.terms_fingerprint,NEW.title,NEW.body,NEW.acknowledgement,CASE WHEN NEW.expires_at IS NULL THEN NULL ELSE to_char(NEW.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END]) THEN RAISE EXCEPTION 'communication_content_hash'; END IF;
  IF NEW.title ~ U&'[\200B\200E\200F\2028-\202E\2060-\206F\FEFF]' OR NEW.body ~ U&'[\200B\200E\200F\2028-\202E\2060-\206F\FEFF]' THEN RAISE EXCEPTION 'communication_unsafe_controls'; END IF;
 ELSIF TG_TABLE_NAME='communication_recipients' THEN
  actor=NEW.employee_id;
  IF c.state='WITHDRAWN' OR NOT EXISTS(SELECT 1 FROM employees WHERE id=actor AND active AND role IN('EMPLOYEE','LEAD')) THEN RAISE EXCEPTION 'communication_recipient_role'; END IF;
  SELECT * INTO r FROM communication_revisions WHERE workspace_id=NEW.workspace_id AND communication_id=NEW.communication_id AND id=NEW.revision_id;
  IF r.id IS NULL OR r.location_id<>NEW.location_id OR r.published_at IS NULL OR NEW.observed_at<>r.audience_observed_at OR
   (r.scope_kind='LOCATION' AND NEW.grant_kind<>'LOCATION') OR
   (r.scope_kind<>'LOCATION' AND NEW.grant_kind<>'ASSIGNMENT') OR
   (r.scope_kind='SHIFT' AND (r.source_shift_id,r.assignment_episode_id,r.terms_fingerprint) IS DISTINCT FROM (NEW.source_shift_id,NEW.assignment_episode_id,NEW.terms_fingerprint)) THEN RAISE EXCEPTION 'communication_grant_context'; END IF;
  SELECT hr.version INTO h FROM communications root JOIN communication_revisions hr ON hr.id=root.head_revision_id WHERE root.id=NEW.communication_id;
  IF h IS NOT NULL AND r.version<=h THEN RAISE EXCEPTION 'communication_audience_frozen'; END IF;
 ELSIF TG_TABLE_NAME='communication_receipts' THEN
  actor=NEW.employee_id;
  IF c.state<>'PUBLISHED' OR c.head_revision_id<>NEW.revision_id THEN RAISE EXCEPTION 'communication_receipt_head'; END IF;
 ELSE actor=NEW.actor_employee_id;
 END IF;
 IF NOT communication_same_workspace(actor,NEW.workspace_id) THEN RAISE EXCEPTION 'communication_actor_workspace'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.company_access_employee_generation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  INSERT INTO operational_subject_versions(workspace_id,employee_id,generation)
   SELECT workspace_id,NEW.id,1 FROM locations WHERE id=NEW.primary_location_id;
 ELSIF NEW.role IS DISTINCT FROM OLD.role OR NEW.active IS DISTINCT FROM OLD.active THEN
  UPDATE operational_subject_versions SET generation=generation+1 WHERE employee_id=NEW.id;
  IF NOT FOUND THEN RAISE EXCEPTION 'company_access_generation_missing'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.company_access_scope_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior integer; canonical text[];
BEGIN
 PERFORM id FROM workspaces WHERE id=NEW.workspace_id FOR NO KEY UPDATE;
 PERFORM id FROM employees WHERE id=NEW.employee_id FOR UPDATE;
 SELECT max(revision) INTO prior FROM operational_scope_revisions WHERE workspace_id=NEW.workspace_id AND employee_id=NEW.employee_id;
 IF NEW.revision<>company_access_next_revision(COALESCE(prior,0)) THEN RAISE EXCEPTION 'company_access_scope_revision'; END IF;
 IF NOT EXISTS(SELECT 1 FROM operational_subject_versions v JOIN employees e ON e.id=v.employee_id
   JOIN locations l ON l.id=e.primary_location_id WHERE v.workspace_id=NEW.workspace_id AND v.employee_id=NEW.employee_id
   AND v.generation=NEW.role_generation AND e.active AND e.role='MANAGER' AND l.workspace_id=NEW.workspace_id)
 THEN RAISE EXCEPTION 'company_access_subject_changed'; END IF;
 IF NEW.mode='LOCATIONS' THEN
  SELECT array_agg(DISTINCT id ORDER BY id) INTO canonical FROM locations
   WHERE workspace_id=NEW.workspace_id AND active AND id=ANY(NEW.location_ids);
  IF canonical IS DISTINCT FROM NEW.location_ids THEN RAISE EXCEPTION 'company_access_scope_locations'; END IF;
 END IF;
 IF NEW.source='LEGACY_ADOPTION' AND (NEW.revision<>1 OR NEW.mode IS DISTINCT FROM 'COMPANY'
   OR EXISTS(SELECT 1 FROM company_access_adoption WHERE workspace_id=NEW.workspace_id))
 THEN RAISE EXCEPTION 'company_access_legacy_adoption_closed'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.native_payroll_guard_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM id FROM workspaces WHERE id=NEW.workspace_id FOR NO KEY UPDATE;
 PERFORM id FROM employees WHERE id=NEW.employee_id FOR UPDATE;
 IF NEW.payload->'result'->>'state' IS DISTINCT FROM 'ready' OR NEW.payload->'result'->>'employeeId' IS DISTINCT FROM NEW.employee_id THEN RAISE EXCEPTION 'INVALID_NATIVE_LEDGER'; END IF;
 IF NOT EXISTS(SELECT 1 FROM payroll_runs_current r WHERE r.workspace_id=NEW.workspace_id AND r.run_id=NEW.run_id AND r.payload->>'status'='APPROVED' AND r.payload->>'sourceAuthority'='NATIVE_RECORDED_TIME') THEN RAISE EXCEPTION 'NATIVE_APPROVAL_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM payroll_runs_current r WHERE r.workspace_id=NEW.workspace_id AND r.run_id=NEW.run_id AND r.payload#>>'{nativeCalculation,state}'='ready'
 AND r.payload#>>'{period,startDate}'=NEW.start_date::text AND r.payload#>>'{period,endDate}'=NEW.end_date::text AND r.payload->>'payday'=NEW.payday::text AND (r.payload->>'correctionOf') IS NOT DISTINCT FROM NEW.correction_of::text
 AND (SELECT count(*) FROM jsonb_array_elements(r.payload#>'{nativeCalculation,employees}') item WHERE item->>'employeeId'=NEW.employee_id)=1
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.payload#>'{nativeCalculation,employees}') item WHERE item=NEW.payload->'result' AND item#>>'{breakdown,taxYear}'=NEW.tax_year::text)) THEN RAISE EXCEPTION 'NATIVE_LEDGER_SNAPSHOT_CONFLICT'; END IF;
 IF NOT EXISTS(SELECT 1 FROM native_payroll_opening_ytd_current y WHERE y.workspace_id=NEW.workspace_id AND y.employee_id=NEW.employee_id AND y.tax_year=NEW.tax_year AND y.revision=NEW.opening_revision) THEN RAISE EXCEPTION 'YTD_SOURCE_CONFLICT'; END IF;
 IF NEW.correction_of IS NULL AND EXISTS(SELECT 1 FROM native_payroll_ledger_heads h WHERE h.workspace_id=NEW.workspace_id AND h.employee_id=NEW.employee_id AND h.start_date<=NEW.end_date AND h.end_date>=NEW.start_date) THEN RAISE EXCEPTION 'OVERLAPPING_NATIVE_PAYROLL'; END IF;
 IF NEW.correction_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM native_payroll_ledger_heads h WHERE h.workspace_id=NEW.workspace_id AND h.employee_id=NEW.employee_id AND h.run_id=NEW.correction_of AND h.tax_year=NEW.tax_year AND h.start_date=NEW.start_date AND h.end_date=NEW.end_date AND h.payday=NEW.payday) THEN RAISE EXCEPTION 'CORRECTION_LINEAGE_CONFLICT'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.nevora_add_workspace_presentation_asset(p_operation uuid, p_workspace text, p_actor text, p_media text, p_width integer, p_height integer, p_bytes bytea, p_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior nevora_workspace_presentation_assets%ROWTYPE; saved nevora_workspace_presentation_assets%ROWTYPE;
BEGIN
 -- The application surrounds this primitive with current-cookie SQL guards.
 IF NOT EXISTS(SELECT 1 FROM employees WHERE id=p_actor AND active AND role='OWNER') OR NOT EXISTS(SELECT 1 FROM workspaces WHERE id=p_workspace AND active) THEN RAISE EXCEPTION 'workspace_presentation_access_denied'; END IF;
 IF p_operation IS NULL OR p_bytes IS NULL OR p_sha IS NULL OR p_sha !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'workspace_presentation_invalid'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('workspace-presentation:'||p_workspace,0));
 SELECT * INTO prior FROM nevora_workspace_presentation_assets WHERE id=p_operation;
 IF FOUND THEN
  IF prior.workspace_id<>p_workspace OR prior.actor_employee_id<>p_actor OR prior.sha256<>p_sha THEN RAISE EXCEPTION 'workspace_presentation_conflict'; END IF;
 ELSE
  INSERT INTO nevora_workspace_presentation_assets(id,workspace_id,actor_employee_id,media_type,width,height,byte_size,sha256,bytes)
  VALUES(p_operation,p_workspace,p_actor,p_media,p_width,p_height,octet_length(p_bytes),p_sha,p_bytes) RETURNING * INTO prior;
 END IF;
 RETURN jsonb_build_object('state','saved','assetId',prior.id::text,'mediaType',prior.media_type,'width',prior.width,'height',prior.height);
END; $function$

CREATE OR REPLACE FUNCTION public.nevora_calendar_authority_loss()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='employees' THEN
  IF NOT NEW.active OR NEW.role NOT IN('EMPLOYEE','LEAD') THEN UPDATE calendar_subscriptions SET revoked_at=clock_timestamp(),revocation_reason='account_loss' WHERE employee_id=NEW.id AND revoked_at IS NULL;
  ELSE UPDATE calendar_subscriptions c SET revoked_at=clock_timestamp(),revocation_reason='location_loss' WHERE c.employee_id=NEW.id AND c.revoked_at IS NULL AND EXISTS(SELECT 1 FROM unnest(c.allowed_location_ids) allowed(id) WHERE allowed.id<>NEW.primary_location_id AND NOT EXISTS(SELECT 1 FROM employee_location_eligibility e WHERE e.employee_id=NEW.id AND e.location_id=allowed.id));END IF;
 ELSIF TG_TABLE_NAME='employee_credentials' THEN
  IF NEW.password_hash IS DISTINCT FROM OLD.password_hash OR NEW.password_updated_at IS DISTINCT FROM OLD.password_updated_at THEN UPDATE calendar_subscriptions SET revoked_at=clock_timestamp(),revocation_reason='credential_reset' WHERE employee_id=NEW.employee_id AND revoked_at IS NULL;END IF;
 ELSIF TG_TABLE_NAME='employee_location_eligibility' THEN
  IF NOT EXISTS(SELECT 1 FROM employees e WHERE e.id=OLD.employee_id AND e.primary_location_id=OLD.location_id) THEN UPDATE calendar_subscriptions SET revoked_at=clock_timestamp(),revocation_reason='location_loss' WHERE employee_id=OLD.employee_id AND OLD.location_id=ANY(allowed_location_ids) AND revoked_at IS NULL;END IF;
 ELSIF TG_TABLE_NAME='locations' THEN
  IF NOT NEW.active THEN UPDATE calendar_subscriptions SET revoked_at=clock_timestamp(),revocation_reason='location_loss' WHERE NEW.id=ANY(allowed_location_ids) AND revoked_at IS NULL;END IF;
 ELSIF TG_TABLE_NAME='workspaces' THEN
  IF NOT NEW.active THEN UPDATE calendar_subscriptions SET revoked_at=clock_timestamp(),revocation_reason='workspace_loss' WHERE workspace_id=NEW.id AND revoked_at IS NULL;END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.nevora_calendar_credential_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'calendar_credential_history';END IF;
 IF NEW.digest IS DISTINCT FROM OLD.digest OR NEW.generation IS DISTINCT FROM OLD.generation OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id OR NEW.allowed_location_ids IS DISTINCT FROM OLD.allowed_location_ids OR NEW.issued_at IS DISTINCT FROM OLD.issued_at OR NEW.id IS DISTINCT FROM OLD.id OR (OLD.revoked_at IS NOT NULL AND (NEW.revoked_at IS DISTINCT FROM OLD.revoked_at OR NEW.revocation_reason IS DISTINCT FROM OLD.revocation_reason)) THEN RAISE EXCEPTION 'calendar_credential_immutable';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.nevora_calendar_source_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='locations' THEN
  IF TG_OP='UPDATE' THEN
   IF NEW.short_name IS NOT DISTINCT FROM OLD.short_name THEN NEW.calendar_serial:=OLD.calendar_serial;NEW.calendar_modified_at:=OLD.calendar_modified_at;RETURN NEW;END IF;
  END IF;
 END IF;
 UPDATE calendar_clock SET serial=serial+1,modified_at=GREATEST(clock_timestamp(),modified_at+interval '1 microsecond') WHERE singleton
 RETURNING serial,modified_at INTO NEW.calendar_serial,NEW.calendar_modified_at;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.nevora_payroll_export_command(p_workspace text, p_actor text, p_operation uuid, p_hash text, p_profile uuid, p_revision integer, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior payroll_export_receipts%ROWTYPE;row_count integer;
BEGIN
 IF p_profile IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('nevora.export.profile.'||p_workspace||p_profile::text,0));END IF;
 SELECT * INTO prior FROM payroll_export_receipts WHERE workspace_id=p_workspace AND actor_employee_id=p_actor AND operation_id=p_operation;
 IF FOUND THEN IF prior.command_hash<>p_hash THEN RAISE EXCEPTION 'nevora_export_CONFLICT';END IF;RETURN prior.payload;END IF;
 IF p_profile IS NOT NULL AND NOT EXISTS(SELECT 1 FROM nevora_payroll_profile_latest WHERE workspace_id=p_workspace AND profile_id=p_profile AND revision=p_revision) THEN RAISE EXCEPTION 'nevora_export_CONFLICT';END IF;
 row_count=jsonb_array_length(p_payload #> '{model,rows}');
 IF row_count<1 OR row_count>100 OR (SELECT count(*) FROM jsonb_array_elements(p_payload #> '{model,rows}') r JOIN nevora_timecard_latest c
 ON c.workspace_id=p_workspace AND c.employee_id=r->>'employeeId' AND c.start_date=(p_payload #>> '{model,period,startDate}')::date
 AND c.end_date=(p_payload #>> '{model,period,endDate}')::date AND c.action='FINALIZE' AND c.revision=(r->>'revision')::integer
 AND c.source_hash=r->>'sourceHash' AND c.operation_id::text=r->>'finalizationOperationId')<>row_count THEN RAISE EXCEPTION 'nevora_export_CONFLICT';END IF;
 IF p_payload #>> '{profile,format}'='ADP_RUN_GENERIC_V1' AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload #> '{model,rows}') r JOIN employees e ON e.id=r->>'employeeId' WHERE NOT e.active) THEN RAISE EXCEPTION 'nevora_export_INACTIVE';END IF;
 INSERT INTO payroll_export_receipts(workspace_id,actor_employee_id,operation_id,command_hash,payload) VALUES(p_workspace,p_actor,p_operation,p_hash,p_payload);
 RETURN p_payload;
END $function$

CREATE OR REPLACE FUNCTION public.nevora_payroll_profile_command(p_workspace text, p_actor text, p_operation uuid, p_profile uuid, p_expected integer, p_hash text, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior payroll_export_profile_revisions%ROWTYPE;current_revision integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('nevora.export.profile.'||p_workspace||p_profile::text,0));
 SELECT * INTO prior FROM payroll_export_profile_revisions WHERE workspace_id=p_workspace AND operation_id=p_operation;
 IF FOUND THEN
  IF prior.actor_employee_id<>p_actor OR prior.command_hash<>p_hash THEN RAISE EXCEPTION 'nevora_export_CONFLICT';END IF;
  RETURN jsonb_build_object('id',prior.profile_id,'revision',prior.revision,'profile',prior.profile);
 END IF;
 SELECT revision INTO current_revision FROM nevora_payroll_profile_latest WHERE workspace_id=p_workspace AND profile_id=p_profile;
 IF current_revision IS NULL AND (SELECT count(*) FROM nevora_payroll_profile_latest WHERE workspace_id=p_workspace)>=100 THEN RAISE EXCEPTION 'nevora_export_PROFILE_LIMIT';END IF;
 IF COALESCE(current_revision,0)<>p_expected THEN RAISE EXCEPTION 'nevora_export_CONFLICT';END IF;
 IF (SELECT count(DISTINCT m->>'employeeId') FROM jsonb_array_elements(p_config->'employeeMappings') m JOIN employees e ON e.id=m->>'employeeId' JOIN locations l ON l.id=e.primary_location_id WHERE l.workspace_id=p_workspace)<>jsonb_array_length(p_config->'employeeMappings') THEN RAISE EXCEPTION 'nevora_export_SCOPE';END IF;
 INSERT INTO payroll_export_profile_revisions(workspace_id,profile_id,revision,operation_id,actor_employee_id,command_hash,profile)
 VALUES(p_workspace,p_profile,p_expected+1,p_operation,p_actor,p_hash,p_config);
 RETURN jsonb_build_object('id',p_profile,'revision',p_expected+1,'profile',p_config);
END $function$

CREATE OR REPLACE FUNCTION public.nevora_review_time_correction(p_operation uuid, p_request uuid, p_actor text, p_expected_revision integer, p_decision text, p_note text, p_operation_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  saved time_correction_events%ROWTYPE;
  request_row time_correction_requests%ROWTYPE;
  entry_row time_entries%ROWTYPE;
  break_row break_entries%ROWTYPE;
  current_revision integer;
  current_kind text;
  current_base uuid;
  target time_correction_adjustments%ROWTYPE;
  target_event time_correction_events%ROWTYPE;
  adjustment_id uuid;
  proposed_start timestamptz;
  proposed_end timestamptz;
  parent_start timestamptz;
  parent_end timestamptz;
  result_data jsonb;
BEGIN
  SELECT * INTO saved FROM time_correction_events WHERE id=p_operation;
  IF FOUND THEN
    IF saved.actor_employee_id<>p_actor OR saved.operation_hash<>p_operation_hash THEN
      RAISE EXCEPTION 'nevora_correction_COMMAND_REUSED';
    END IF;
    RETURN saved.result;
  END IF;

  SELECT * INTO request_row
  FROM time_correction_requests WHERE id=p_request
  FOR UPDATE;
  IF request_row.id IS NULL THEN RAISE EXCEPTION 'nevora_correction_NOT_FOUND'; END IF;

  PERFORM id FROM employees
  WHERE id=ANY(ARRAY[p_actor,request_row.employee_id])
  ORDER BY id FOR UPDATE;

  IF p_actor=request_row.employee_id THEN
    RAISE EXCEPTION 'nevora_correction_SELF_REVIEW';
  END IF;
  PERFORM e.id
  FROM employees e JOIN locations home ON home.id=e.primary_location_id
  WHERE e.id=p_actor AND e.active AND e.role IN ('OWNER','MANAGER')
    AND home.workspace_id=request_row.workspace_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'nevora_correction_AUTH_REQUIRED'; END IF;

  SELECT revision,event_kind INTO current_revision,current_kind
  FROM time_correction_events WHERE request_id=p_request
  ORDER BY revision DESC LIMIT 1;
  IF current_revision IS NULL OR current_revision<>p_expected_revision
     OR current_kind IS DISTINCT FROM 'REQUESTED' THEN
    RAISE EXCEPTION 'nevora_correction_STALE_STATE';
  END IF;
  IF p_decision NOT IN ('APPROVE','REJECT')
     OR p_expected_revision<1
     OR p_operation_hash !~ '^[a-f0-9]{64}$'
     OR (p_note IS NOT NULL AND (
       p_note<>btrim(p_note) OR char_length(p_note) NOT BETWEEN 1 AND 500 OR p_note ~ '[[:cntrl:]]'
     )) THEN RAISE EXCEPTION 'nevora_correction_INVALID'; END IF;

  IF p_decision='REJECT' THEN
    result_data=jsonb_build_object(
      'status','rejected','operationId',p_operation,'requestId',p_request,
      'revision',current_revision+1
    );
    INSERT INTO time_correction_events(
      id,request_id,revision,event_kind,actor_employee_id,operation_hash,decision_note,result
    ) VALUES (
      p_operation,p_request,current_revision+1,'REJECTED',p_actor,p_operation_hash,p_note,result_data
    );
    RETURN result_data;
  END IF;

  INSERT INTO clocker_employee_clock_state(employee_id) VALUES(request_row.employee_id)
    ON CONFLICT DO NOTHING;
  PERFORM employee_id FROM clocker_employee_clock_state
  WHERE employee_id=request_row.employee_id FOR UPDATE;

  proposed_start=(request_row.proposal->>'startAt')::timestamptz;
  proposed_end=(request_row.proposal->>'endAt')::timestamptz;
  IF proposed_start>=proposed_end OR proposed_end>clock_timestamp() THEN
    RAISE EXCEPTION 'nevora_correction_INVALID_INTERVAL';
  END IF;

  IF request_row.kind='ENTRY_BOUNDARY' THEN
    SELECT t.* INTO entry_row
    FROM time_entries t WHERE t.id=request_row.time_entry_id
      AND t.employee_id=request_row.employee_id
    FOR UPDATE;
    IF entry_row.id IS NULL OR entry_row.clock_out_at IS NULL OR entry_row.status<>'CLOCKED_OUT' THEN
      RAISE EXCEPTION 'nevora_correction_LIVE_STATE';
    END IF;
    IF entry_row.version<>(request_row.source_snapshot->>'sourceVersion')::integer THEN
      RAISE EXCEPTION 'nevora_correction_STALE_SOURCE';
    END IF;
    SELECT a.id INTO current_base FROM nevora_time_correction_leaf_adjustments a
      WHERE a.kind='ENTRY_BOUNDARY' AND a.time_entry_id=entry_row.id;
    IF current_base IS DISTINCT FROM request_row.base_adjustment_id THEN
      RAISE EXCEPTION 'nevora_correction_STALE_SOURCE';
    END IF;
    IF EXISTS (
      SELECT 1 FROM nevora_effective_break_entries child
      WHERE child.time_entry_id=entry_row.id
        AND (child.end_at IS NULL OR child.start_at>=child.end_at
          OR child.start_at<proposed_start OR child.end_at>proposed_end)
    ) THEN RAISE EXCEPTION 'nevora_correction_INVALID_INTERVAL'; END IF;
    IF EXISTS (
      SELECT 1 FROM nevora_effective_time_entries other
      WHERE other.employee_id=request_row.employee_id
        AND other.time_entry_id IS DISTINCT FROM request_row.time_entry_id
        AND proposed_start<COALESCE(other.end_at,'infinity'::timestamptz)
        AND other.start_at<proposed_end
    ) THEN RAISE EXCEPTION 'nevora_correction_OVERLAP'; END IF;
  ELSIF request_row.kind='BREAK_BOUNDARY' THEN
    SELECT t.* INTO entry_row
    FROM time_entries t WHERE t.id=request_row.time_entry_id
      AND t.employee_id=request_row.employee_id
    FOR UPDATE;
    SELECT b.* INTO break_row
    FROM break_entries b WHERE b.id=request_row.break_entry_id
      AND b.time_entry_id=request_row.time_entry_id
    FOR UPDATE;
    IF entry_row.id IS NULL OR entry_row.clock_out_at IS NULL
       OR break_row.id IS NULL OR break_row.break_end_at IS NULL THEN
      RAISE EXCEPTION 'nevora_correction_LIVE_STATE';
    END IF;
    IF entry_row.version<>(request_row.source_snapshot->>'entryVersion')::integer
       OR break_row.version<>(request_row.source_snapshot->>'sourceVersion')::integer THEN
      RAISE EXCEPTION 'nevora_correction_STALE_SOURCE';
    END IF;
    SELECT a.id INTO current_base FROM nevora_time_correction_leaf_adjustments a
      WHERE a.kind='BREAK_BOUNDARY' AND a.break_entry_id=break_row.id;
    IF current_base IS DISTINCT FROM request_row.base_adjustment_id THEN
      RAISE EXCEPTION 'nevora_correction_STALE_SOURCE';
    END IF;
    SELECT start_at,end_at INTO parent_start,parent_end
    FROM nevora_effective_time_entries
    WHERE employee_id=request_row.employee_id AND time_entry_id=request_row.time_entry_id;
    IF parent_start IS NULL OR parent_end IS NULL
       OR proposed_start<parent_start OR proposed_end>parent_end THEN
      RAISE EXCEPTION 'nevora_correction_INVALID_INTERVAL';
    END IF;
    IF EXISTS (
      SELECT 1 FROM nevora_effective_break_entries other
      WHERE other.time_entry_id=request_row.time_entry_id
        AND other.break_entry_id<>request_row.break_entry_id
        AND proposed_start<COALESCE(other.end_at,'infinity'::timestamptz)
        AND other.start_at<proposed_end
    ) THEN RAISE EXCEPTION 'nevora_correction_OVERLAP'; END IF;
  ELSE
    IF request_row.base_adjustment_id IS NOT NULL THEN
      SELECT * INTO target FROM nevora_time_correction_leaf_adjustments
        WHERE id=request_row.base_adjustment_id AND kind='MISSING_ENTRY'
          AND workspace_id=request_row.workspace_id AND employee_id=request_row.employee_id
          AND location_id=request_row.location_id;
      IF target.id IS NULL THEN RAISE EXCEPTION 'nevora_correction_STALE_SOURCE'; END IF;
      SELECT * INTO target_event FROM time_correction_events
        WHERE request_id=target.request_id ORDER BY revision DESC LIMIT 1;
      IF target_event.event_kind IS DISTINCT FROM 'APPROVED'
         OR target_event.adjustment_id IS DISTINCT FROM target.id
         OR target_event.revision IS DISTINCT FROM (request_row.source_snapshot->>'targetRevision')::integer
         OR target.id IS DISTINCT FROM (request_row.source_snapshot->>'targetAdjustmentId')::uuid
         OR target.request_id IS DISTINCT FROM (request_row.source_snapshot->>'targetRequestId')::uuid THEN
        RAISE EXCEPTION 'nevora_correction_STALE_SOURCE';
      END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM nevora_effective_time_entries other
      WHERE other.employee_id=request_row.employee_id
        -- Exclude only the independently revalidated explicit target; NULL excludes nothing.
        AND (request_row.base_adjustment_id IS NULL OR other.adjustment_id IS DISTINCT FROM request_row.base_adjustment_id)
        AND proposed_start<COALESCE(other.end_at,'infinity'::timestamptz)
        AND other.start_at<proposed_end
    ) THEN RAISE EXCEPTION 'nevora_correction_OVERLAP'; END IF;
  END IF;

  adjustment_id=p_operation;
  INSERT INTO time_correction_adjustments(
    id,request_id,workspace_id,employee_id,kind,time_entry_id,break_entry_id,location_id,
    effective_start_at,effective_end_at,source_revision,source_snapshot,
    supersedes_adjustment_id,created_by
  ) VALUES (
    adjustment_id,request_row.id,request_row.workspace_id,request_row.employee_id,request_row.kind,
    request_row.time_entry_id,request_row.break_entry_id,request_row.location_id,
    proposed_start,proposed_end,request_row.source_revision,request_row.source_snapshot,
    request_row.base_adjustment_id,p_actor
  );

  result_data=jsonb_build_object(
    'status','approved','operationId',p_operation,'requestId',p_request,
    'revision',current_revision+1,'adjustmentId',adjustment_id
  );
  INSERT INTO time_correction_events(
    id,request_id,revision,event_kind,actor_employee_id,operation_hash,decision_note,adjustment_id,result
  ) VALUES (
    p_operation,p_request,current_revision+1,'APPROVED',p_actor,p_operation_hash,
    p_note,adjustment_id,result_data
  );
  RETURN result_data;
END;
$function$

CREATE OR REPLACE FUNCTION public.nevora_set_company_policy(p_operation uuid, p_workspace text, p_location text, p_actor text, p_expected integer, p_settings jsonb, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior nevora_company_policy_revisions%ROWTYPE; latest nevora_company_policy_revisions%ROWTYPE; saved nevora_company_policy_revisions%ROWTYPE; before_settings jsonb; changes jsonb;
BEGIN
 -- The application surrounds this primitive with canonical current-cookie SQL
 -- guards, ordered locks and final expiry checks. It is never authentication.
 IF NOT EXISTS(SELECT 1 FROM employees WHERE id=p_actor AND active AND role='OWNER') OR NOT EXISTS(SELECT 1 FROM workspaces WHERE id=p_workspace AND active) THEN RAISE EXCEPTION 'company_policy_access_denied'; END IF;
 IF p_location IS NOT NULL AND NOT EXISTS(SELECT 1 FROM locations WHERE id=p_location AND workspace_id=p_workspace AND active) THEN RAISE EXCEPTION 'company_policy_access_denied'; END IF;
 IF p_expected IS NULL OR p_expected<0 OR p_expected>2147483646 OR p_operation IS NULL OR p_hash IS NULL OR p_hash !~ '^[a-f0-9]{64}$' OR p_settings IS NULL OR jsonb_typeof(p_settings)<>'object' OR p_settings->>'version' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'company_policy_invalid'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('company-policy:'||p_workspace||':'||COALESCE(p_location,''),0));
 SELECT * INTO prior FROM nevora_company_policy_revisions WHERE operation_id=p_operation;
 IF FOUND THEN
  IF prior.workspace_id<>p_workspace OR prior.location_id IS DISTINCT FROM p_location OR prior.actor_employee_id<>p_actor OR prior.command_hash<>p_hash OR prior.settings<>p_settings THEN RAISE EXCEPTION 'company_policy_conflict'; END IF;
  RETURN jsonb_build_object('state','saved','operationId',prior.operation_id::text,'revision',prior.revision,'locationId',prior.location_id,'changedAt',prior.changed_at::text,'changedKeys',prior.changed_keys);
 END IF;
 -- Scope every customer labor input independently, including company scopes.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(NULLIF(p_settings#>'{labor,rates}','null'::jsonb),'[]'::jsonb)) r
  WHERE NOT EXISTS(SELECT 1 FROM employees e WHERE e.id=r->>'employeeId')
   OR (r->>'locationId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM locations l WHERE l.id=r->>'locationId' AND l.workspace_id=p_workspace AND l.active))
   OR (p_location IS NOT NULL AND (r->>'locationId') IS DISTINCT FROM p_location)) THEN RAISE EXCEPTION 'company_policy_access_denied'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(NULLIF(p_settings#>'{labor,budgets}','null'::jsonb),'[]'::jsonb)) b
  WHERE (b->>'locationId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM locations l WHERE l.id=b->>'locationId' AND l.workspace_id=p_workspace AND l.active))
   OR (p_location IS NOT NULL AND (b->>'locationId') IS DISTINCT FROM p_location)) THEN RAISE EXCEPTION 'company_policy_access_denied'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(COALESCE(p_settings#>'{labor,compensation,excludedBreakTypeIds}','[]'::jsonb)) AS excluded(break_id)
  WHERE NOT EXISTS(SELECT 1 FROM clocker_break_types b WHERE b.id=excluded.break_id AND b.workspace_id=p_workspace)) THEN RAISE EXCEPTION 'company_policy_access_denied'; END IF;
 SELECT * INTO latest FROM nevora_company_policy_revisions WHERE workspace_id=p_workspace AND location_id IS NOT DISTINCT FROM p_location ORDER BY revision DESC LIMIT 1;
 IF COALESCE(latest.revision,0)<>p_expected THEN RAISE EXCEPTION 'company_policy_conflict'; END IF;
 before_settings=COALESCE(latest.settings,'{"version":1}'::jsonb);
 WITH paths AS(SELECT section||'.'||field AS path,section,field FROM(SELECT 'attendance' AS section UNION SELECT 'labor') sections CROSS JOIN LATERAL (
  SELECT jsonb_object_keys(COALESCE(before_settings->section,'{}'::jsonb)) AS field UNION SELECT jsonb_object_keys(COALESCE(p_settings->section,'{}'::jsonb))
 ) fields)
 SELECT COALESCE(jsonb_agg(path ORDER BY path),'[]'::jsonb) INTO changes FROM paths WHERE before_settings#>ARRAY[section,field] IS DISTINCT FROM p_settings#>ARRAY[section,field];
 INSERT INTO nevora_company_policy_revisions(operation_id,workspace_id,location_id,revision,actor_employee_id,command_hash,previous_settings,settings,changed_keys)
 VALUES(p_operation,p_workspace,p_location,p_expected+1,p_actor,p_hash,before_settings,p_settings,changes) RETURNING * INTO saved;
 RETURN jsonb_build_object('state','saved','operationId',saved.operation_id::text,'revision',saved.revision,'locationId',saved.location_id,'changedAt',saved.changed_at::text,'changedKeys',saved.changed_keys);
END; $function$

CREATE OR REPLACE FUNCTION public.nevora_set_workspace_presentation(p_operation uuid, p_workspace text, p_actor text, p_expected integer, p_settings jsonb, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior nevora_workspace_presentation_revisions%ROWTYPE; latest nevora_workspace_presentation_revisions%ROWTYPE; saved nevora_workspace_presentation_revisions%ROWTYPE;
 before_settings jsonb; changes jsonb; logo text; newly_off text[]; waiting integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM employees WHERE id=p_actor AND active AND role='OWNER') OR NOT EXISTS(SELECT 1 FROM workspaces WHERE id=p_workspace AND active) THEN RAISE EXCEPTION 'workspace_presentation_access_denied'; END IF;
 IF p_expected IS NULL OR p_expected<0 OR p_expected>2147483646 OR p_operation IS NULL OR p_hash IS NULL OR p_hash !~ '^[a-f0-9]{64}$' OR p_settings IS NULL OR jsonb_typeof(p_settings)<>'object' OR p_settings->>'version' IS DISTINCT FROM '1' OR jsonb_typeof(p_settings->'brand') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'workspace_presentation_invalid'; END IF;
 IF p_settings ? 'words' AND (jsonb_typeof(p_settings->'words')<>'object' OR (p_settings#>>'{words,preset}') IS NULL OR (p_settings#>>'{words,preset}') NOT IN ('standard','retail','restaurant','field','care')) THEN RAISE EXCEPTION 'workspace_presentation_invalid'; END IF;
 IF p_settings ? 'modules' AND (jsonb_typeof(p_settings->'modules')<>'object' OR jsonb_typeof(p_settings#>'{modules,disabled}') IS DISTINCT FROM 'array'
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_settings#>'{modules,disabled}') m WHERE jsonb_typeof(m)<>'string' OR m#>>'{}' NOT IN ('timeOff','marketplace','updates','payStatements','breaks'))) THEN RAISE EXCEPTION 'workspace_presentation_invalid'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('workspace-presentation:'||p_workspace,0));
 SELECT * INTO prior FROM nevora_workspace_presentation_revisions WHERE operation_id=p_operation;
 IF FOUND THEN
  IF prior.workspace_id<>p_workspace OR prior.actor_employee_id<>p_actor OR prior.command_hash<>p_hash OR prior.settings<>p_settings THEN RAISE EXCEPTION 'workspace_presentation_conflict'; END IF;
  RETURN jsonb_build_object('state','saved','operationId',prior.operation_id::text,'revision',prior.revision,'changedAt',prior.changed_at::text,'changedKeys',prior.changed_keys);
 END IF;
 logo=p_settings#>>'{brand,logoAssetId}';
 IF logo IS NOT NULL AND NOT EXISTS(SELECT 1 FROM nevora_workspace_presentation_assets a WHERE a.id::text=logo AND a.workspace_id=p_workspace) THEN RAISE EXCEPTION 'workspace_presentation_access_denied'; END IF;
 SELECT * INTO latest FROM nevora_workspace_presentation_revisions WHERE workspace_id=p_workspace ORDER BY revision DESC LIMIT 1;
 IF COALESCE(latest.revision,0)<>p_expected THEN RAISE EXCEPTION 'workspace_presentation_conflict'; END IF;
 before_settings=COALESCE(latest.settings,'{"version":1,"brand":{}}'::jsonb);
 -- Turning a module off must not strand requests that are still waiting.
 -- Each database holds one workspace (workspaces.singleton), so these request
 -- tables carry no workspace column and every row belongs to p_workspace.
 SELECT COALESCE(array_agg(m),'{}') INTO newly_off FROM jsonb_array_elements_text(COALESCE(p_settings#>'{modules,disabled}','[]'::jsonb)) m
  WHERE NOT COALESCE(before_settings#>'{modules,disabled}','[]'::jsonb) ? m;
 IF 'timeOff'=ANY(newly_off) THEN
  SELECT count(*) INTO waiting FROM time_off_requests WHERE status='PENDING';
  IF waiting>0 THEN RAISE EXCEPTION 'workspace_presentation_module_busy:timeOff:%',waiting; END IF;
 END IF;
 IF 'marketplace'=ANY(newly_off) THEN
  SELECT (SELECT count(*) FROM shift_exchanges WHERE status IN ('OPEN','EMPLOYEE_PENDING','MANAGER_PENDING'))
   +(SELECT count(*) FROM shift_callouts WHERE status='PENDING') INTO waiting;
  IF waiting>0 THEN RAISE EXCEPTION 'workspace_presentation_module_busy:marketplace:%',waiting; END IF;
 END IF;
 WITH paths AS(SELECT section||'.'||field AS path,section,field FROM (SELECT unnest(ARRAY['brand','words','modules']) AS section) sections CROSS JOIN LATERAL (
  SELECT jsonb_object_keys(CASE WHEN jsonb_typeof(before_settings->section)='object' THEN before_settings->section ELSE '{}'::jsonb END) AS field
  UNION SELECT jsonb_object_keys(CASE WHEN jsonb_typeof(p_settings->section)='object' THEN p_settings->section ELSE '{}'::jsonb END)
 ) fields)
 SELECT COALESCE(jsonb_agg(path ORDER BY path),'[]'::jsonb) INTO changes FROM paths WHERE before_settings#>ARRAY[section,field] IS DISTINCT FROM p_settings#>ARRAY[section,field];
 INSERT INTO nevora_workspace_presentation_revisions(operation_id,workspace_id,revision,actor_employee_id,command_hash,previous_settings,settings,changed_keys)
 VALUES(p_operation,p_workspace,p_expected+1,p_actor,p_hash,before_settings,p_settings,changes) RETURNING * INTO saved;
 RETURN jsonb_build_object('state','saved','operationId',saved.operation_id::text,'revision',saved.revision,'changedAt',saved.changed_at::text,'changedKeys',saved.changed_keys);
END; $function$

CREATE OR REPLACE FUNCTION public.nevora_submit_time_correction(p_request uuid, p_workspace text, p_employee text, p_actor text, p_kind text, p_time_entry text, p_break_entry text, p_location text, p_proposed_start timestamp with time zone, p_proposed_end timestamp with time zone, p_reason text, p_request_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  existing time_correction_requests%ROWTYPE;
  entry_row time_entries%ROWTYPE;
  break_row break_entries%ROWTYPE;
  source_rev integer;
  source_data jsonb;
  base_id uuid;
  actual_location text;
  parent_start timestamptz;
  parent_end timestamptz;
  result_data jsonb;
BEGIN
  SELECT * INTO existing FROM time_correction_requests WHERE id=p_request;
  IF FOUND THEN
    IF existing.employee_id<>p_employee OR existing.requested_by_employee_id<>p_actor
       OR existing.request_hash<>p_request_hash THEN
      RAISE EXCEPTION 'nevora_correction_COMMAND_REUSED';
    END IF;
    SELECT result INTO result_data FROM time_correction_events WHERE id=p_request;
    IF result_data IS NULL THEN RAISE EXCEPTION 'nevora_correction_INTEGRITY'; END IF;
    RETURN result_data;
  END IF;

  IF p_actor IS DISTINCT FROM p_employee
     OR p_kind NOT IN ('ENTRY_BOUNDARY','BREAK_BOUNDARY','MISSING_ENTRY')
     OR p_proposed_start IS NULL OR p_proposed_end IS NULL
     OR p_proposed_start>=p_proposed_end
     OR p_proposed_end>clock_timestamp()
     OR p_request_hash !~ '^[a-f0-9]{64}$'
     OR p_reason IS NULL OR p_reason<>btrim(p_reason)
     OR char_length(p_reason) NOT BETWEEN 1 AND 500
     OR p_reason ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'nevora_correction_INVALID';
  END IF;

  PERFORM e.id
  FROM employees e
  JOIN locations home ON home.id=e.primary_location_id
  WHERE e.id=p_employee AND e.active AND home.workspace_id=p_workspace
  FOR UPDATE OF e;
  IF NOT FOUND THEN RAISE EXCEPTION 'nevora_correction_AUTH_REQUIRED'; END IF;

  INSERT INTO clocker_employee_clock_state(employee_id) VALUES(p_employee)
    ON CONFLICT DO NOTHING;
  SELECT revision INTO source_rev
  FROM clocker_employee_clock_state
  WHERE employee_id=p_employee
  FOR UPDATE;
  IF source_rev IS NULL THEN RAISE EXCEPTION 'nevora_correction_INTEGRITY'; END IF;

  IF p_kind='ENTRY_BOUNDARY' THEN
    IF p_time_entry IS NULL OR p_break_entry IS NOT NULL THEN
      RAISE EXCEPTION 'nevora_correction_INVALID';
    END IF;
    SELECT t.* INTO entry_row
    FROM time_entries t JOIN locations l ON l.id=t.location_id
    WHERE t.id=p_time_entry AND t.employee_id=p_employee AND l.workspace_id=p_workspace
    FOR UPDATE OF t;
    IF entry_row.id IS NULL THEN RAISE EXCEPTION 'nevora_correction_NOT_FOUND'; END IF;
    IF entry_row.clock_out_at IS NULL OR entry_row.status<>'CLOCKED_OUT' THEN
      RAISE EXCEPTION 'nevora_correction_LIVE_STATE';
    END IF;
    actual_location=entry_row.location_id;
    SELECT a.id INTO base_id
    FROM nevora_time_correction_leaf_adjustments a
    WHERE a.kind='ENTRY_BOUNDARY' AND a.time_entry_id=entry_row.id;
    source_data=jsonb_build_object(
      'recorded',true,'timeEntryId',entry_row.id,'sourceVersion',entry_row.version,
      'clockInAt',entry_row.clock_in_at,'clockOutAt',entry_row.clock_out_at,
      'locationId',entry_row.location_id,'deviceId',entry_row.device_id,
      'scheduleContext',entry_row.schedule_context
    );
    IF EXISTS (
      SELECT 1 FROM nevora_pending_time_corrections pending
      WHERE pending.employee_id=p_employee
        AND pending.kind='ENTRY_BOUNDARY'
        AND pending.time_entry_id=entry_row.id
    ) THEN RAISE EXCEPTION 'nevora_correction_PENDING_EXISTS'; END IF;
  ELSIF p_kind='BREAK_BOUNDARY' THEN
    IF p_time_entry IS NULL OR p_break_entry IS NULL THEN
      RAISE EXCEPTION 'nevora_correction_INVALID';
    END IF;
    SELECT t.* INTO entry_row
    FROM time_entries t JOIN locations l ON l.id=t.location_id
    WHERE t.id=p_time_entry AND t.employee_id=p_employee AND l.workspace_id=p_workspace
    FOR UPDATE OF t;
    IF entry_row.id IS NULL THEN RAISE EXCEPTION 'nevora_correction_NOT_FOUND'; END IF;
    IF entry_row.clock_out_at IS NULL OR entry_row.status<>'CLOCKED_OUT' THEN
      RAISE EXCEPTION 'nevora_correction_LIVE_STATE';
    END IF;
    SELECT b.* INTO break_row
    FROM break_entries b
    WHERE b.id=p_break_entry AND b.time_entry_id=entry_row.id
    FOR UPDATE OF b;
    IF break_row.id IS NULL OR break_row.break_end_at IS NULL THEN
      RAISE EXCEPTION 'nevora_correction_LIVE_STATE';
    END IF;
    SELECT start_at,end_at INTO parent_start,parent_end
    FROM nevora_effective_time_entries
    WHERE employee_id=p_employee AND time_entry_id=entry_row.id;
    IF parent_start IS NULL OR parent_end IS NULL
       OR p_proposed_start<parent_start OR p_proposed_end>parent_end THEN
      RAISE EXCEPTION 'nevora_correction_INVALID_INTERVAL';
    END IF;
    actual_location=entry_row.location_id;
    SELECT a.id INTO base_id
    FROM nevora_time_correction_leaf_adjustments a
    WHERE a.kind='BREAK_BOUNDARY' AND a.break_entry_id=break_row.id;
    source_data=jsonb_build_object(
      'recorded',true,'timeEntryId',entry_row.id,'entryVersion',entry_row.version,
      'breakEntryId',break_row.id,'sourceVersion',break_row.version,
      'startAt',break_row.break_start_at,'endAt',break_row.break_end_at,
      'breakTypeId',break_row.break_type_id,'breakTypeSnapshot',break_row.break_type_snapshot,
      'locationId',entry_row.location_id
    );
    IF EXISTS (
      SELECT 1 FROM nevora_pending_time_corrections pending
      WHERE pending.employee_id=p_employee
        AND pending.kind='BREAK_BOUNDARY'
        AND pending.break_entry_id=break_row.id
    ) THEN RAISE EXCEPTION 'nevora_correction_PENDING_EXISTS'; END IF;
  ELSE
    IF p_time_entry IS NOT NULL OR p_break_entry IS NOT NULL OR p_location IS NULL THEN
      RAISE EXCEPTION 'nevora_correction_INVALID';
    END IF;
    PERFORM l.id
    FROM locations l
    JOIN employee_location_eligibility elig
      ON elig.location_id=l.id AND elig.employee_id=p_employee
    WHERE l.id=p_location AND l.workspace_id=p_workspace AND l.active
    FOR SHARE OF l;
    IF NOT FOUND THEN RAISE EXCEPTION 'nevora_correction_AUTH_REQUIRED'; END IF;
    actual_location=p_location;
    source_data=jsonb_build_object('recorded',false,'locationId',p_location);
    IF EXISTS (
      SELECT 1 FROM nevora_pending_time_corrections pending
      WHERE pending.employee_id=p_employee AND pending.kind='MISSING_ENTRY'
        AND (pending.proposal->>'startAt')::timestamptz < p_proposed_end
        AND p_proposed_start < (pending.proposal->>'endAt')::timestamptz
    ) THEN RAISE EXCEPTION 'nevora_correction_PENDING_EXISTS'; END IF;
  END IF;

  INSERT INTO time_correction_requests(
    id,workspace_id,employee_id,requested_by_employee_id,kind,time_entry_id,break_entry_id,
    location_id,source_revision,source_snapshot,base_adjustment_id,proposal,reason,request_hash
  ) VALUES (
    p_request,p_workspace,p_employee,p_actor,p_kind,p_time_entry,p_break_entry,
    actual_location,source_rev,source_data,base_id,
    jsonb_build_object('startAt',p_proposed_start,'endAt',p_proposed_end),
    p_reason,p_request_hash
  );

  result_data=jsonb_build_object(
    'status','pending','operationId',p_request,'requestId',p_request,'revision',1
  );
  INSERT INTO time_correction_events(
    id,request_id,revision,event_kind,actor_employee_id,operation_hash,result
  ) VALUES (p_request,p_request,1,'REQUESTED',p_actor,p_request_hash,result_data);
  RETURN result_data;
END;
$function$

CREATE OR REPLACE FUNCTION public.nevora_submit_time_correction(p_request uuid, p_workspace text, p_employee text, p_actor text, p_kind text, p_time_entry text, p_break_entry text, p_location text, p_proposed_start timestamp with time zone, p_proposed_end timestamp with time zone, p_reason text, p_request_hash text, p_target_adjustment uuid, p_expected_base_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  existing time_correction_requests%ROWTYPE;
  target time_correction_adjustments%ROWTYPE;
  target_event time_correction_events%ROWTYPE;
  source_rev integer;
  source_data jsonb;
  result_data jsonb;
BEGIN
  SELECT * INTO existing FROM time_correction_requests WHERE id=p_request;
  IF FOUND THEN
    IF existing.workspace_id IS DISTINCT FROM p_workspace
       OR existing.employee_id IS DISTINCT FROM p_employee
       OR existing.requested_by_employee_id IS DISTINCT FROM p_actor
       OR existing.base_adjustment_id IS DISTINCT FROM p_target_adjustment
       OR existing.request_hash IS DISTINCT FROM p_request_hash THEN
      RAISE EXCEPTION 'nevora_correction_COMMAND_REUSED';
    END IF;
    SELECT result INTO result_data FROM time_correction_events WHERE id=p_request;
    IF result_data IS NULL THEN RAISE EXCEPTION 'nevora_correction_INTEGRITY'; END IF;
    RETURN result_data;
  END IF;

  IF p_actor IS DISTINCT FROM p_employee OR p_kind IS DISTINCT FROM 'MISSING_ENTRY'
     OR p_time_entry IS NOT NULL OR p_break_entry IS NOT NULL OR p_location IS NULL
     OR p_target_adjustment IS NULL OR p_expected_base_revision IS NULL OR p_expected_base_revision<1
     OR p_proposed_start IS NULL OR p_proposed_end IS NULL OR p_proposed_start>=p_proposed_end
     OR p_proposed_end>clock_timestamp()
     OR p_request_hash IS NULL OR p_request_hash !~ '^[a-f0-9]{64}$'
     OR p_reason IS NULL OR p_reason<>btrim(p_reason)
     OR char_length(p_reason) NOT BETWEEN 1 AND 500 OR p_reason ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'nevora_correction_INVALID';
  END IF;

  PERFORM e.id FROM employees e JOIN locations home ON home.id=e.primary_location_id
    WHERE e.id=p_employee AND e.active AND home.workspace_id=p_workspace FOR UPDATE OF e;
  IF NOT FOUND THEN RAISE EXCEPTION 'nevora_correction_AUTH_REQUIRED'; END IF;
  PERFORM l.id FROM locations l JOIN employee_location_eligibility elig
    ON elig.location_id=l.id AND elig.employee_id=p_employee
    WHERE l.id=p_location AND l.workspace_id=p_workspace AND l.active FOR SHARE OF l;
  IF NOT FOUND THEN RAISE EXCEPTION 'nevora_correction_AUTH_REQUIRED'; END IF;

  INSERT INTO clocker_employee_clock_state(employee_id) VALUES(p_employee) ON CONFLICT DO NOTHING;
  SELECT revision INTO source_rev FROM clocker_employee_clock_state
    WHERE employee_id=p_employee FOR UPDATE;
  IF source_rev IS NULL THEN RAISE EXCEPTION 'nevora_correction_INTEGRITY'; END IF;

  SELECT * INTO target FROM time_correction_adjustments
    WHERE id=p_target_adjustment AND kind='MISSING_ENTRY'
      AND employee_id=p_employee AND workspace_id=p_workspace AND location_id=p_location;
  IF target.id IS NULL THEN RAISE EXCEPTION 'nevora_correction_NOT_FOUND'; END IF;
  SELECT * INTO target_event FROM time_correction_events
    WHERE request_id=target.request_id ORDER BY revision DESC LIMIT 1;
  IF NOT EXISTS (SELECT 1 FROM nevora_time_correction_leaf_adjustments WHERE id=target.id)
     OR target_event.event_kind IS DISTINCT FROM 'APPROVED'
     OR target_event.adjustment_id IS DISTINCT FROM target.id
     OR target_event.revision IS DISTINCT FROM p_expected_base_revision THEN
    RAISE EXCEPTION 'nevora_correction_STALE_SOURCE';
  END IF;

  -- Preserve the existing pending-proposal overlap protection, including adjacency.
  IF EXISTS (
    SELECT 1 FROM nevora_pending_time_corrections pending
    WHERE pending.employee_id=p_employee AND pending.kind='MISSING_ENTRY'
      AND (pending.proposal->>'startAt')::timestamptz < p_proposed_end
      AND p_proposed_start < (pending.proposal->>'endAt')::timestamptz
  ) THEN RAISE EXCEPTION 'nevora_correction_PENDING_EXISTS'; END IF;

  source_data=jsonb_build_object(
    'recorded',false,'locationId',target.location_id,
    'targetAdjustmentId',target.id,'targetRequestId',target.request_id,
    'targetRevision',target_event.revision,
    'startAt',target.effective_start_at,'endAt',target.effective_end_at
  );
  INSERT INTO time_correction_requests(
    id,workspace_id,employee_id,requested_by_employee_id,kind,time_entry_id,break_entry_id,
    location_id,source_revision,source_snapshot,base_adjustment_id,proposal,reason,request_hash
  ) VALUES (
    p_request,p_workspace,p_employee,p_actor,'MISSING_ENTRY',NULL,NULL,
    target.location_id,source_rev,source_data,target.id,
    jsonb_build_object('startAt',p_proposed_start,'endAt',p_proposed_end),p_reason,p_request_hash
  );
  result_data=jsonb_build_object('status','pending','operationId',p_request,'requestId',p_request,'revision',1);
  INSERT INTO time_correction_events(id,request_id,revision,event_kind,actor_employee_id,operation_hash,result)
    VALUES(p_request,p_request,1,'REQUESTED',p_actor,p_request_hash,result_data);
  RETURN result_data;
END;
$function$

CREATE OR REPLACE FUNCTION public.nevora_template_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.workspace_id IS DISTINCT FROM OLD.workspace_id OR (TG_TABLE_NAME='schedule_template_shifts' AND to_jsonb(NEW)->>'template_id' IS DISTINCT FROM to_jsonb(OLD)->>'template_id')) THEN RAISE EXCEPTION 'template ownership is immutable'; END IF;
 IF NEW.workspace_id IS NULL THEN NEW.workspace_id:=(SELECT id FROM workspaces WHERE singleton=true AND active); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.nevora_timecard_command(p_operation uuid, p_workspace text, p_employee text, p_actor text, p_start date, p_end date, p_expected integer, p_source_hash text, p_action text, p_note text, p_command_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior timecard_revisions%ROWTYPE; latest timecard_revisions%ROWTYPE; source_data jsonb; actual_hash text; after_at timestamptz; next_revision integer;
BEGIN
  PERFORM id FROM employees WHERE id IN(p_employee,p_actor) ORDER BY id FOR UPDATE;
  SELECT * INTO prior FROM timecard_revisions WHERE operation_id=p_operation;
  IF FOUND THEN
    IF prior.workspace_id<>p_workspace OR prior.actor_employee_id<>p_actor OR prior.command_hash<>p_command_hash THEN RAISE EXCEPTION 'nevora_timecard_CONFLICT'; END IF;
    RETURN jsonb_build_object('status',CASE prior.action WHEN 'APPROVE' THEN 'approved' WHEN 'FINALIZE' THEN 'finalized' ELSE 'reopened' END,
      'operationId',p_operation,'revision',prior.revision);
  END IF;
  IF p_actor=p_employee THEN RAISE EXCEPTION 'nevora_timecard_SELF_REVIEW'; END IF;
  IF NOT EXISTS(SELECT 1 FROM employees WHERE id=p_actor AND active AND role IN('OWNER','MANAGER')) THEN RAISE EXCEPTION 'nevora_timecard_AUTH_REQUIRED'; END IF;
  IF p_action NOT IN('APPROVE','FINALIZE','REOPEN') OR p_expected<0 OR p_expected IS NULL OR p_source_hash !~ '^[a-f0-9]{32}$' OR p_command_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'nevora_timecard_INVALID'; END IF;
  source_data=nevora_timecard_source(p_workspace,p_employee,p_start,p_end);
  actual_hash=md5(source_data::text);
  SELECT * INTO latest FROM nevora_timecard_latest WHERE workspace_id=p_workspace AND employee_id=p_employee AND start_date=p_start AND end_date=p_end;
  IF COALESCE(latest.revision,0)<>p_expected THEN RAISE EXCEPTION 'nevora_timecard_CONFLICT'; END IF;
  IF EXISTS(SELECT 1 FROM nevora_timecard_latest WHERE workspace_id=p_workspace AND employee_id=p_employee AND action='FINALIZE'
    AND start_date<=p_end AND end_date>=p_start AND (start_date<>p_start OR end_date<>p_end)) THEN RAISE EXCEPTION 'nevora_timecard_OVERLAPPING_PERIOD'; END IF;
  -- Reopen acknowledges the immutable finalized revision displayed by readers.
  -- Approve/finalize still validate the live canonical source.
  IF p_action='REOPEN' THEN
    IF latest.source_hash IS DISTINCT FROM p_source_hash THEN RAISE EXCEPTION 'nevora_timecard_CONFLICT'; END IF;
  ELSIF actual_hash<>p_source_hash THEN RAISE EXCEPTION 'nevora_timecard_CONFLICT'; END IF;
  after_at=(p_end+1)::timestamp AT TIME ZONE (source_data->>'timeZone');
  IF p_action='REOPEN' THEN
    IF latest.action IS DISTINCT FROM 'FINALIZE' OR p_note IS NULL OR btrim(p_note)='' THEN RAISE EXCEPTION 'nevora_timecard_STATE'; END IF;
  ELSE
    IF latest.action='FINALIZE' THEN RAISE EXCEPTION 'nevora_timecard_STATE'; END IF;
    IF after_at>clock_timestamp() OR (source_data->>'pendingCorrections')::integer>0 OR EXISTS(
      SELECT 1 FROM jsonb_array_elements(source_data->'entries') e WHERE e->>'endAt' IS NULL
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(e->'breaks') b WHERE b->>'endAt' IS NULL)) THEN RAISE EXCEPTION 'nevora_timecard_UNRESOLVED'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(source_data->'entries') a JOIN jsonb_array_elements(source_data->'entries') b
      ON a->>'id'<b->>'id' WHERE (a->>'startAt')::timestamptz<(b->>'endAt')::timestamptz AND (b->>'startAt')::timestamptz<(a->>'endAt')::timestamptz)
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(source_data->'entries') e CROSS JOIN LATERAL jsonb_array_elements(e->'breaks') b
      WHERE (b->>'startAt')::timestamptz<(e->>'startAt')::timestamptz OR (b->>'endAt')::timestamptz>(e->>'endAt')::timestamptz
      OR (b->>'endAt')::timestamptz<=(b->>'startAt')::timestamptz) THEN RAISE EXCEPTION 'nevora_timecard_UNRESOLVED'; END IF;
    IF p_action='FINALIZE' AND (latest.action IS DISTINCT FROM 'APPROVE' OR latest.source_hash<>actual_hash) THEN RAISE EXCEPTION 'nevora_timecard_APPROVAL_REQUIRED'; END IF;
  END IF;
  next_revision=COALESCE(latest.revision,0)+1;
  INSERT INTO timecard_revisions(operation_id,workspace_id,employee_id,start_date,end_date,revision,action,actor_employee_id,
    source_hash,snapshot,command_hash,note) VALUES(p_operation,p_workspace,p_employee,p_start,p_end,next_revision,p_action,p_actor,actual_hash,source_data,p_command_hash,p_note);
  RETURN jsonb_build_object('status',CASE p_action WHEN 'APPROVE' THEN 'approved' WHEN 'FINALIZE' THEN 'finalized' ELSE 'reopened' END,
    'operationId',p_operation,'revision',next_revision);
END;
$function$

CREATE OR REPLACE FUNCTION public.nevora_timecard_correction_interlock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original_start timestamptz; original_end timestamptz; proposed_start timestamptz; proposed_end timestamptz;
BEGIN
  PERFORM id FROM employees WHERE id=NEW.employee_id FOR UPDATE;
  IF TG_TABLE_NAME='time_correction_requests' THEN
    proposed_start=(NEW.proposal->>'startAt')::timestamptz; proposed_end=(NEW.proposal->>'endAt')::timestamptz;
  ELSE proposed_start=NEW.effective_start_at; proposed_end=NEW.effective_end_at; END IF;
  IF NEW.time_entry_id IS NOT NULL THEN
    SELECT clock_in_at,clock_out_at INTO original_start,original_end FROM time_entries WHERE id=NEW.time_entry_id;
  ELSIF TG_TABLE_NAME='time_correction_requests' THEN
    SELECT effective_start_at,effective_end_at INTO original_start,original_end FROM time_correction_adjustments WHERE id=NEW.base_adjustment_id;
  ELSE
    SELECT effective_start_at,effective_end_at INTO original_start,original_end FROM time_correction_adjustments WHERE id=NEW.supersedes_adjustment_id;
  END IF;
  IF EXISTS(SELECT 1 FROM nevora_timecard_latest c JOIN workspaces w ON w.id=c.workspace_id
    WHERE c.employee_id=NEW.employee_id AND c.workspace_id=NEW.workspace_id AND c.action='FINALIZE' AND (
      (proposed_start<(c.end_date+1)::timestamp AT TIME ZONE w.time_zone AND proposed_end>c.start_date::timestamp AT TIME ZONE w.time_zone)
      OR (original_start<(c.end_date+1)::timestamp AT TIME ZONE w.time_zone AND COALESCE(original_end,'infinity'::timestamptz)>c.start_date::timestamp AT TIME ZONE w.time_zone))) THEN
    RAISE EXCEPTION 'nevora_correction_FINALIZED_PERIOD';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.nevora_timecard_raw_interlock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE employee text; location text; first_at timestamptz; after_at timestamptz;
 old_employee text; old_location text; old_first timestamptz; old_after timestamptz;
BEGIN
 IF TG_TABLE_NAME='time_entries' THEN
  IF TG_OP='DELETE' THEN
   employee=OLD.employee_id;location=OLD.location_id;first_at=OLD.clock_in_at;after_at=OLD.clock_out_at;
  ELSE
   employee=NEW.employee_id;location=NEW.location_id;first_at=NEW.clock_in_at;after_at=NEW.clock_out_at;
  END IF;
  IF TG_OP='UPDATE' THEN
   old_employee=OLD.employee_id;old_location=OLD.location_id;old_first=OLD.clock_in_at;old_after=OLD.clock_out_at;
  END IF;
 ELSE
  IF TG_OP='DELETE' THEN
   SELECT employee_id,location_id,clock_in_at,clock_out_at INTO employee,location,first_at,after_at FROM time_entries WHERE id=OLD.time_entry_id;
  ELSE
   SELECT employee_id,location_id,clock_in_at,clock_out_at INTO employee,location,first_at,after_at FROM time_entries WHERE id=NEW.time_entry_id;
  END IF;
  IF TG_OP='UPDATE' THEN
   SELECT employee_id,location_id,clock_in_at,clock_out_at INTO old_employee,old_location,old_first,old_after FROM time_entries WHERE id=OLD.time_entry_id;
  END IF;
 END IF;
 PERFORM id FROM employees WHERE id=ANY(ARRAY[employee,old_employee]) ORDER BY id FOR UPDATE;
 IF EXISTS(
  SELECT 1 FROM (VALUES (employee,location,first_at,after_at),(old_employee,old_location,old_first,old_after)) AS p(employee_id,location_id,first_at,after_at)
  JOIN locations l ON l.id=p.location_id JOIN workspaces w ON w.id=l.workspace_id
  JOIN nevora_timecard_latest c ON c.workspace_id=w.id AND c.employee_id=p.employee_id
  WHERE c.action='FINALIZE' AND p.first_at<(c.end_date+1)::timestamp AT TIME ZONE w.time_zone
   AND COALESCE(p.after_at,'infinity'::timestamptz)>c.start_date::timestamp AT TIME ZONE w.time_zone
 ) THEN RAISE EXCEPTION 'nevora_timecard_FINALIZED_PERIOD'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.nevora_timecard_source(p_workspace text, p_employee text, p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE zone text; first_at timestamptz; after_at timestamptz; entry_data jsonb; correction_data jsonb; pending integer; employee_name text;
BEGIN
  IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>30 THEN RAISE EXCEPTION 'nevora_timecard_INVALID'; END IF;
  SELECT time_zone INTO zone FROM workspaces WHERE id=p_workspace AND active;
  SELECT trim(e.first_name||' '||e.last_name) INTO employee_name FROM employees e JOIN locations l ON l.id=e.primary_location_id
    WHERE e.id=p_employee AND l.workspace_id=p_workspace;
  IF zone IS NULL OR employee_name IS NULL THEN RAISE EXCEPTION 'nevora_timecard_AUTH_REQUIRED'; END IF;
  first_at=p_start::timestamp AT TIME ZONE zone; after_at=(p_end+1)::timestamp AT TIME ZONE zone;
  IF (SELECT count(*) FROM nevora_effective_time_entries v JOIN locations l ON l.id=v.location_id
      WHERE v.employee_id=p_employee AND l.workspace_id=p_workspace AND v.start_at<after_at AND (v.end_at IS NULL OR v.end_at>first_at))>10000 THEN
    RAISE EXCEPTION 'nevora_timecard_SOURCE_LIMIT';
  END IF;
  SELECT COALESCE(jsonb_agg(value ORDER BY start_at,id),'[]'::jsonb) INTO entry_data FROM (
    SELECT v.start_at,COALESCE(v.time_entry_id,v.adjustment_id::text) AS id,
      jsonb_build_object('id',COALESCE(v.time_entry_id,v.adjustment_id::text),'locationId',v.location_id,
        'locationName',COALESCE(NULLIF(trim(l.short_name),''),trim(l.name)),
        'positionId',t.schedule_context->'match'->>'positionId','positionName',t.schedule_context->'match'->>'positionName',
        'sourceKind',v.source_kind,'adjustmentId',v.adjustment_id,'recordedVersion',v.recorded_version,
        'startAt',v.start_at::text,'endAt',v.end_at::text,'rawStartAt',t.clock_in_at::text,'rawEndAt',t.clock_out_at::text,
        'breaks',COALESCE(b.items,'[]'::jsonb)) AS value
    FROM nevora_effective_time_entries v JOIN locations l ON l.id=v.location_id
    LEFT JOIN time_entries t ON t.id=v.time_entry_id
    LEFT JOIN LATERAL (
      SELECT jsonb_agg(jsonb_build_object('id',eb.break_entry_id,'startAt',eb.start_at::text,'endAt',eb.end_at::text,
        'rawStartAt',rb.break_start_at::text,'rawEndAt',rb.break_end_at::text,'adjustmentId',eb.adjustment_id,
        'name',COALESCE(NULLIF(eb.break_type_snapshot->>'name',''),'Recorded break')) ORDER BY eb.start_at,eb.break_entry_id) AS items
      FROM nevora_effective_break_entries eb JOIN break_entries rb ON rb.id=eb.break_entry_id
      WHERE eb.time_entry_id=v.time_entry_id AND eb.employee_id=p_employee
    ) b ON true
    WHERE v.employee_id=p_employee AND l.workspace_id=p_workspace AND v.start_at<after_at AND (v.end_at IS NULL OR v.end_at>first_at)
  ) entries;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(entry_data) e WHERE jsonb_array_length(e->'breaks')>1000) THEN RAISE EXCEPTION 'nevora_timecard_SOURCE_LIMIT'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',r.id,'kind',r.kind,
      'status',CASE e.event_kind WHEN 'APPROVED' THEN 'APPROVED' WHEN 'REJECTED' THEN 'REJECTED' ELSE 'PENDING' END,
      'reason',r.reason,'revision',e.revision,'startAt',r.proposal->>'startAt','endAt',r.proposal->>'endAt') ORDER BY r.created_at,r.id),'[]'::jsonb),
      count(*) FILTER(WHERE e.event_kind='REQUESTED')::integer INTO correction_data,pending
    FROM time_correction_requests r
    JOIN LATERAL(SELECT event_kind,revision FROM time_correction_events WHERE request_id=r.id ORDER BY revision DESC LIMIT 1) e ON true
    LEFT JOIN time_entries t ON t.id=r.time_entry_id
    WHERE r.workspace_id=p_workspace AND r.employee_id=p_employee AND (
      ((r.proposal->>'startAt')::timestamptz<after_at AND (r.proposal->>'endAt')::timestamptz>first_at)
      OR (t.clock_in_at<after_at AND (t.clock_out_at IS NULL OR t.clock_out_at>first_at))
      OR EXISTS(SELECT 1 FROM time_correction_adjustments a WHERE a.id=r.base_adjustment_id AND a.effective_start_at<after_at AND a.effective_end_at>first_at));
  IF jsonb_array_length(correction_data)>10000 THEN RAISE EXCEPTION 'nevora_timecard_SOURCE_LIMIT'; END IF;
  RETURN jsonb_build_object('employeeId',p_employee,'employeeName',employee_name,'timeZone',zone,
    'startDate',p_start::text,'endDate',p_end::text,'pendingCorrections',pending,'entries',entry_data,'corrections',correction_data);
END;
$function$

CREATE OR REPLACE FUNCTION public.owner_advisor_reserve(w text, o text, r uuid, h text, cap integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior owner_advisor_requests; used integer;
BEGIN
 IF cap NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'invalid cap'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('owner-advisor:'||w,0));
 UPDATE owner_advisor_requests SET state='failed' WHERE workspace_id=w AND state='running' AND lease_until<=clock_timestamp();
 SELECT * INTO prior FROM owner_advisor_requests WHERE workspace_id=w AND owner_id=o AND request_id=r;
 IF FOUND THEN
  IF prior.command_hash<>h OR prior.kind<>'ask' THEN RETURN jsonb_build_object('error','conflict'); END IF;
  IF prior.state='completed' AND prior.result IS NOT NULL THEN RETURN jsonb_build_object('replay',prior.result); END IF;
  RETURN jsonb_build_object('error',CASE WHEN prior.state='running' THEN 'busy' ELSE 'prior_attempt_failed' END);
 END IF;
 SELECT count(*) INTO used FROM owner_advisor_requests WHERE workspace_id=w AND kind='ask' AND created_at>=date_trunc('day',clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
 IF used>=cap THEN RETURN jsonb_build_object('error','daily_limit'); END IF;
 IF EXISTS(SELECT 1 FROM owner_advisor_requests WHERE workspace_id=w AND kind='ask' AND state='running') THEN RETURN jsonb_build_object('error','busy'); END IF;
 INSERT INTO owner_advisor_requests(workspace_id,owner_id,request_id,command_hash,kind,state) VALUES(w,o,r,h,'ask','running');
 RETURN jsonb_build_object('admitted',true);
END $function$

CREATE OR REPLACE FUNCTION public.owner_advisor_review_briefing(w text, o text, r uuid, h text, i text, f text, d date, k text, l text, p jsonb, expected integer, choice text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior owner_advisor_requests; current_revision integer; answer jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('owner-advisor:'||w,0));
 SELECT * INTO prior FROM owner_advisor_requests WHERE workspace_id=w AND owner_id=o AND request_id=r;
 IF FOUND THEN
  IF prior.command_hash<>h OR prior.kind<>'review_briefing' THEN RETURN jsonb_build_object('error','conflict'); END IF;
  RETURN prior.result;
 END IF;
 DELETE FROM owner_advisor_briefing_reviews WHERE workspace_id=w AND owner_id=o AND issue_date<d-14;
 DELETE FROM owner_advisor_requests WHERE workspace_id=w AND owner_id=o AND kind='review_briefing' AND created_at<clock_timestamp()-interval '14 days';
 SELECT revision INTO current_revision FROM owner_advisor_briefing_reviews WHERE workspace_id=w AND owner_id=o AND issue_id=i FOR UPDATE;
 IF COALESCE(current_revision,0)<>expected THEN RETURN jsonb_build_object('error','conflict'); END IF;
 IF current_revision IS NULL THEN
  DELETE FROM owner_advisor_briefing_reviews WHERE workspace_id=w AND owner_id=o AND issue_id IN(
   SELECT issue_id FROM owner_advisor_briefing_reviews WHERE workspace_id=w AND owner_id=o ORDER BY updated_at DESC,issue_id OFFSET 49);
 END IF;
 INSERT INTO owner_advisor_briefing_reviews(workspace_id,owner_id,issue_id,fingerprint,issue_date,kind,location_id,proof,disposition,deferred_until,revision)
 VALUES(w,o,i,f,d,k,l,p,choice,CASE WHEN choice='deferred' THEN clock_timestamp()+interval '1 hour' ELSE NULL END,1)
 ON CONFLICT(workspace_id,owner_id,issue_id) DO UPDATE SET fingerprint=EXCLUDED.fingerprint,proof=EXCLUDED.proof,disposition=EXCLUDED.disposition,deferred_until=EXCLUDED.deferred_until,revision=owner_advisor_briefing_reviews.revision+1,updated_at=clock_timestamp()
 RETURNING jsonb_build_object('revision',revision) INTO answer;
 INSERT INTO owner_advisor_requests(workspace_id,owner_id,request_id,command_hash,kind,state,result) VALUES(w,o,r,h,'review_briefing','completed',answer);
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.owner_advisor_save(w text, o text, r uuid, h text, expected integer, value text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE prior owner_advisor_requests; result jsonb; current_revision integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('owner-advisor:'||w,0));
 SELECT * INTO prior FROM owner_advisor_requests WHERE workspace_id=w AND owner_id=o AND request_id=r;
 IF FOUND THEN
  IF prior.command_hash<>h OR prior.kind<>'save_priorities' THEN RETURN jsonb_build_object('error','conflict'); END IF;
  RETURN prior.result;
 END IF;
 INSERT INTO owner_advisor_profiles(workspace_id,owner_id) VALUES(w,o) ON CONFLICT DO NOTHING;
 SELECT revision INTO current_revision FROM owner_advisor_profiles WHERE workspace_id=w AND owner_id=o FOR UPDATE;
 IF current_revision<>expected THEN RETURN jsonb_build_object('error','conflict'); END IF;
 UPDATE owner_advisor_profiles SET priorities=value,revision=revision+1 WHERE workspace_id=w AND owner_id=o RETURNING jsonb_build_object('priorities',priorities,'revision',revision) INTO result;
 INSERT INTO owner_advisor_requests(workspace_id,owner_id,request_id,command_hash,kind,state,result) VALUES(w,o,r,h,'save_priorities','completed',result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.shift_assignment_episode()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 IF TG_OP='INSERT' OR NEW.employee_id IS DISTINCT FROM OLD.employee_id THEN
   NEW.assignment_episode_id := gen_random_uuid();
 ELSE
   -- Callers cannot resurrect a past episode, including on same-owner edits.
   NEW.assignment_episode_id := OLD.assignment_episode_id;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.shift_change_reserve_callout()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 DELETE FROM shift_change_participation WHERE callout_id=NEW.id;
 IF NEW.status='PENDING' OR (NEW.status='APPROVED' AND NOT NEW.legacy_manual AND NOT EXISTS (
   SELECT 1 FROM shift_exchanges WHERE linked_callout_id=NEW.id
 )) THEN
   INSERT INTO shift_change_participation(shift_id,callout_id,role) VALUES (NEW.shift_id,NEW.id,'CALLOUT');
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.shift_change_reserve_exchange()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 DELETE FROM shift_change_participation WHERE exchange_id=NEW.id;
 IF NEW.status IN ('OPEN','EMPLOYEE_PENDING','MANAGER_PENDING') THEN
   IF NEW.linked_callout_id IS NOT NULL THEN
     IF NEW.kind <> 'COVERAGE' OR NOT EXISTS (
       SELECT 1 FROM shift_callouts c JOIN shifts s ON s.id=c.shift_id
       WHERE c.id=NEW.linked_callout_id AND c.status='APPROVED' AND NOT c.legacy_manual
         AND c.shift_id=NEW.source_shift_id AND c.employee_id=NEW.requested_by_employee_id
         AND c.employee_id=s.employee_id AND c.assignment_episode_id=s.assignment_episode_id
     ) THEN RAISE EXCEPTION 'shift_change_invalid_callout_link'; END IF;
     DELETE FROM shift_change_participation WHERE callout_id=NEW.linked_callout_id AND shift_id=NEW.source_shift_id;
   END IF;
   INSERT INTO shift_change_participation(shift_id,exchange_id,role) VALUES (NEW.source_shift_id,NEW.id,'SOURCE');
   IF NEW.target_shift_id IS NOT NULL THEN INSERT INTO shift_change_participation(shift_id,exchange_id,role) VALUES (NEW.target_shift_id,NEW.id,'TARGET'); END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.shift_material_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 IF TG_OP='INSERT' THEN NEW.terms_revision:=1;
 ELSIF ROW(NEW.schedule_id,NEW.date,NEW.start_time,NEW.end_time,NEW.position_id,NEW.is_designated_lead)
   IS DISTINCT FROM ROW(OLD.schedule_id,OLD.date,OLD.start_time,OLD.end_time,OLD.position_id,OLD.is_designated_lead)
   OR (pg_trigger_depth()>1 AND NEW.terms_revision IS DISTINCT FROM OLD.terms_revision) THEN
   NEW.terms_revision:=OLD.terms_revision+1;
 ELSE NEW.terms_revision:=OLD.terms_revision; END IF;
 RETURN NEW;
END $function$
